/** Ein Text aus TEXTE in der Sprache des Prozesses — siehe `inSprache`. */
function tx(schluessel, werte) {
  return textAus(TEXTE, schluessel, werte);
}

/**
 * Führt `fn` in der Sprache `sprache` aus und stellt danach die vorige wieder her. Der Server
 * arbeitet über mehrere Projekte: Jede Antwort spricht die Sprache ihres Projekts, und keine
 * sickert in die nächste oder in einen Aufrufer im selben Prozess.
 */
function inSprache(sprache, fn) {
  const vorher = prozessSprache();
  spracheFestlegen(sprache);
  try {
    return fn();
  } finally {
    spracheFestlegen(vorher);
  }
}

