/** Genau die Schlüsselwörter, die das Schema benutzt — ein Test hält beide gleich. */
export const SCHLUESSELWOERTER = [
  "type", "enum", "const", "pattern", "oneOf", "not", "required", "minItems", "minProperties",
  "additionalProperties", "properties", "items", "minLength", "minimum", "exclusiveMinimum", "maximum", "uniqueItems",
];

const istObjekt = (w) => w !== null && typeof w === "object" && !Array.isArray(w);
/**
 * Der Wert als Objekt — alles andere (auch `null` und Listen) wird zum leeren Objekt.
 *
 * Steht als Funktionsdeklaration da und wiederholt die Bedingung aus `istObjekt`, weil sie
 * ueber `GRUPPEN_QUELLE` per `toString()` ins Browser-Skript wandert: Dort gibt es kein
 * `istObjekt`, und eine Arrow-Konstante brauchte ihre Deklaration mit.
 */
function objektOder(w) {
  return w !== null && typeof w === "object" && !Array.isArray(w) ? w : {};
}

function typName(wert) {
  if (wert === null) return "null";
  if (Array.isArray(wert)) return "array";
  if (Number.isInteger(wert)) return "integer";
  return typeof wert;
}

function passtTyp(wert, erwartet) {
  const liste = Array.isArray(erwartet) ? erwartet : [erwartet];
  const ist = typName(wert);
  return liste.some((t) => t === ist || (t === "number" && ist === "integer"));
}

const pfadVon = (basis, schluessel) => (basis ? `${basis}.${schluessel}` : String(schluessel));

/**
 * Ein Befund. `art` ist `fehler` (hält das Speichern auf), `unbekannt` (ein Feld, das diese
 * Oberfläche nicht kennt) oder `warnung` (ein Mangel, der genannt gehört, das Speichern aber
 * nicht aufhält — Plan #721 E7). Nur `fehler` wertet `speichere` aus; die beiden anderen
 * Arten sind Anzeige.
 */
function befund(pfad, grund, art = "fehler") {
  return { pfad, art, grund };
}

function pruefeText(wert, schema, pfad, out) {
  if (schema.pattern !== undefined && !new RegExp(schema.pattern, "u").test(wert)) out.push(befund(pfad, tx("pruefe.muster", { muster: schema.pattern })));
  if (schema.minLength !== undefined && wert.length < schema.minLength) out.push(befund(pfad, tx("pruefe.minLength", { n: schema.minLength })));
}

function pruefeZahl(wert, schema, pfad, out) {
  if (schema.minimum !== undefined && wert < schema.minimum) out.push(befund(pfad, tx("pruefe.minimum", { n: schema.minimum })));
  if (schema.exclusiveMinimum !== undefined && wert <= schema.exclusiveMinimum) out.push(befund(pfad, tx("pruefe.exclusiveMinimum", { n: schema.exclusiveMinimum })));
  if (schema.maximum !== undefined && wert > schema.maximum) out.push(befund(pfad, tx("pruefe.maximum", { n: schema.maximum })));
}

/** Die Prüfungen, die sich auf einen einzelnen Wert beziehen; `false` bei falschem Typ. */
function pruefeSkalar(wert, schema, pfad, out) {
  if (schema.type !== undefined && !passtTyp(wert, schema.type)) {
    out.push(befund(pfad, tx("pruefe.typ", { typ: [schema.type].flat().join(tx("pruefe.oder")), ist: typName(wert) })));
    return false;
  }
  if (Array.isArray(schema.enum) && !schema.enum.some((e) => JSON.stringify(e) === JSON.stringify(wert))) {
    out.push(befund(pfad, tx("pruefe.enum", { werte: schema.enum.map((e) => JSON.stringify(e)).join(", ") })));
  }
  if (Object.hasOwn(schema, "const") && JSON.stringify(schema.const) !== JSON.stringify(wert)) {
    out.push(befund(pfad, tx("pruefe.const", { wert: JSON.stringify(schema.const) })));
  }
  if (typeof wert === "string") pruefeText(wert, schema, pfad, out);
  if (typeof wert === "number") pruefeZahl(wert, schema, pfad, out);
  return true;
}

function pruefeListe(wert, schema, pfad, out) {
  if (schema.minItems !== undefined && wert.length < schema.minItems) out.push(befund(pfad, tx("pruefe.minItems", { n: schema.minItems })));
  if (schema.uniqueItems === true && new Set(wert.map((w) => JSON.stringify(w))).size !== wert.length) out.push(befund(pfad, tx("pruefe.doppelt")));
  if (istObjekt(schema.items)) wert.forEach((eintrag, i) => pruefeKnoten(eintrag, schema.items, `${pfad}[${i}]`, out));
}

function pruefeObjekt(wert, schema, pfad, out) {
  for (const feld of schema.required ?? []) {
    if (!(feld in wert)) out.push(befund(pfadVon(pfad, feld), tx("pruefe.fehlt")));
  }
  if (schema.minProperties !== undefined && Object.keys(wert).length < schema.minProperties) out.push(befund(pfad || tx("pruefe.wurzel"), tx("pruefe.minItems", { n: schema.minProperties })));
  const bekannt = schema.properties ?? {};
  for (const [feld, kind] of Object.entries(wert)) {
    const p = pfadVon(pfad, feld);
    if (feld in bekannt) pruefeKnoten(kind, bekannt[feld], p, out);
    else if (schema.additionalProperties === false) out.push(befund(p, tx("pruefe.unbekannt"), "unbekannt"));
    else if (istObjekt(schema.additionalProperties)) pruefeKnoten(kind, schema.additionalProperties, p, out);
  }
}

/** Nur die Fehler eines Teilschemas — für oneOf und not, wo Warnungen nicht zählen. */
function nurFehler(wert, schema, pfad) {
  const out = [];
  pruefeKnoten(wert, schema, pfad, out);
  return out.filter((b) => b.art === "fehler");
}

function pruefeVerknuepfungen(wert, schema, pfad, out) {
  if (Array.isArray(schema.oneOf)) {
    const treffer = schema.oneOf.filter((teil) => nurFehler(wert, teil, pfad).length === 0).length;
    if (treffer !== 1) out.push(befund(pfad || tx("pruefe.wurzel"), treffer === 0 ? tx("pruefe.keineForm") : tx("pruefe.mehrereFormen")));
  }
  if (istObjekt(schema.not) && nurFehler(wert, schema.not, pfad).length === 0) {
    out.push(befund(pfad || tx("pruefe.wurzel"), tx("pruefe.ausgeschlossen")));
  }
}

function pruefeKnoten(wert, schema, pfad, out) {
  if (!istObjekt(schema)) return;
  if (!pruefeSkalar(wert, schema, pfad, out)) return;
  if (Array.isArray(wert)) pruefeListe(wert, schema, pfad, out);
  else if (istObjekt(wert)) pruefeObjekt(wert, schema, pfad, out);
  pruefeVerknuepfungen(wert, schema, pfad, out);
}

/**
 * Prüft einen Wert gegen ein Schema. Liefert `[{ pfad, art, grund }]` mit `art` aus
 * `fehler`, `unbekannt` oder `warnung`; `unbekannt` nur für Felder, die
 * `additionalProperties: false` ausschließt (Plan #674 E5). `warnung` vergeben die Regeln
 * über mehrere Felder (Plan #721 E7) — aus dem Schema allein entsteht keine.
 */
export function pruefeSchema(wert, schema = SCHEMA) {
  const out = [];
  pruefeKnoten(wert, schema, "", out);
  return out;
}

// ============================================================
// Regeln über mehrere Felder (Plan #674 E18)
// ============================================================
//
// Das Schema kennt nur das Reviewer-Paar als Regel über zwei Felder. Diese Regeln brechen
// heute erst im Lauf; die Oberfläche soll sie vor dem Speichern nennen.

// SYNC: Laufzeitregel in kit/board/issue-review.mjs, validateReviewStufen — rollen.length gleich reviewer.
function regelRollenzahl(config) {
  const out = [];
  for (const [stufe, eintrag] of Object.entries(istObjekt(config.reviewStufen) ? config.reviewStufen : {})) {
    if (!istObjekt(eintrag) || !Array.isArray(eintrag.rollen) || !Number.isInteger(eintrag.reviewer)) continue;
    if (eintrag.rollen.length !== eintrag.reviewer) {
      out.push(befund(`reviewStufen.${stufe}.rollen`, tx("regel.rollenzahl", { rollen: eintrag.rollen.length, reviewer: eintrag.reviewer })));
    }
  }
  return out;
}

// Rein eine Hilfe der Oberfläche (Plan #721, Kriterium 4a) — kit/board/issue-review.mjs prüft
// Rollennamen nicht gegen den Katalog, nur ihre Zahl, dass sie nicht leer und nicht doppelt
// sind. Ein Name außerhalb des Katalogs bricht deshalb nichts im Nachtbetrieb; er hat nur
// keinen Prompt in issue-review.
function regelRollenKatalog(config) {
  const out = [];
  for (const [stufe, eintrag] of Object.entries(istObjekt(config.reviewStufen) ? config.reviewStufen : {})) {
    if (!istObjekt(eintrag) || !Array.isArray(eintrag.rollen)) continue;
    const katalog = ROLLEN_KATALOG[stufe] ?? [];
    eintrag.rollen.forEach((rolle, i) => {
      if (!katalog.includes(rolle)) {
        out.push(befund(`reviewStufen.${stufe}.rollen[${i}]`, tx("regel.rolleUnbekannt", { rolle, katalog: katalog.join(", ") || tx("regel.keine") })));
      }
    });
  }
  return out;
}

// SYNC: Laufzeitregel in kit/board/issue-review.mjs, validatePairs — Namen aus reviewers, kein Autor prüft sich selbst.
function regelPaare(config) {
  const block = istObjekt(config.issueReview) ? config.issueReview : {};
  const bekannt = new Set((Array.isArray(block.reviewers) ? block.reviewers : []).map((r) => r?.name));
  const out = [];
  for (const [autor, genannt] of Object.entries(istObjekt(block.pairs) ? block.pairs : {})) {
    for (const name of Array.isArray(genannt) ? genannt : []) {
      const pfad = `issueReview.pairs.${autor}`;
      if (name === autor) out.push(befund(pfad, tx("regel.paarSelbst", { autor })));
      else if (!bekannt.has(name)) out.push(befund(pfad, tx("regel.paarUnbekannt", { name })));
    }
  }
  return out;
}

// SYNC: Laufzeitregel in kit/board/issue-review.mjs, validateReviewers — dieselben Fälle, an denen
// sie hart abbricht. `kind` und der Typ von `lesegrenze` fehlen hier bewusst: Das Schema führt
// an `kind` ein `enum` und an `lesegrenze` den Typ und meldet einen falschen Wert schon selbst. Ohne diese Regel speichert die Oberfläche eine
// Config, die gültig aussieht und an der /issue-review danach abbricht (Issue #816).
function regelReviewerFelder(config) {
  const block = istObjekt(config.issueReview) ? config.issueReview : {};
  const out = [];
  (Array.isArray(block.reviewers) ? block.reviewers : []).forEach((r, i) => {
    if (!istObjekt(r)) return;
    const pfad = `issueReview.reviewers[${i}]`;
    if (typeof r.name !== "string" || !r.name) out.push(befund(`${pfad}.name`, tx("regel.nameFehlt")));
    if (r.kind === "claude" && !r.model) out.push(befund(`${pfad}.model`, tx("regel.modelFehlt")));
    if (r.kind === "command" && !r.command) out.push(befund(`${pfad}.command`, tx("regel.commandFehlt")));
    if (r.lesegrenze !== undefined && r.kind !== "command") out.push(befund(`${pfad}.lesegrenze`, tx("regel.lesegrenze")));
  });
  return out;
}

// SYNC: Laufzeitregel in kit/checks.mjs, pruefeBereichsnamen — jedes areas steht in checkAreas.
function regelBereiche(config) {
  const bekannt = new Set(Object.keys(istObjekt(config.checkAreas) ? config.checkAreas : {}));
  const out = [];
  (Array.isArray(config.buildChecks) ? config.buildChecks : []).forEach((check, i) => {
    const fremd = (Array.isArray(check?.areas) ? check.areas : []).filter((name) => !bekannt.has(name));
    const genannt = fremd.map((n) => "'" + n + "'").join(", ");
    if (fremd.length > 0) out.push(befund(`buildChecks[${i}].areas`, tx("regel.bereicheFremd", { genannt })));
  });
  return out;
}

// Ein Bereich ohne Muster erfasst nichts — jeder buildChecks-Eintrag, der auf ihn zeigt,
// läuft dann nie. Das ist kein Fehler: Die Config ist gültig, und ein Bereich, dessen Muster
// noch fehlen, soll sich speichern lassen. Deshalb eine Warnung (Plan #721, Kriterium 20).
function regelLeereBereiche(config) {
  const out = [];
  for (const [name, muster] of Object.entries(istObjekt(config.checkAreas) ? config.checkAreas : {})) {
    if (Array.isArray(muster) && muster.length === 0) {
      out.push(befund(`checkAreas.${name}`, tx("regel.bereichLeer"), "warnung"));
    }
  }
  return out;
}

// Die drei Zeitpunkte einer Pflichtprüfung, in der Reihenfolge des Prozesses.
// SYNC: `STUFEN` in kit/checks.mjs und das enum in templates/workflow.config.schema.json.
const CHECK_STUFEN = ["paket", "push", "merge"];

/** Die Stufe eines `buildChecks`-Eintrags, wie `checks.mjs` sie liest: ein fehlendes Feld ist `paket`. */
function stufeVon(eintrag) {
  return istObjekt(eintrag) && "stufe" in eintrag ? eintrag.stufe : CHECK_STUFEN[0];
}

// SYNC: Laufzeitregel in kit/checks.mjs, `STUFEN` — die Stufe eines Eintrags ist einer der drei
// Namen. Das Schema-oneOf fängt einen fremden Wert bereits ab, meldet aber nur "passt auf keine
// der erlaubten Formen" — dieselbe Lage wie bei night.stufen (Issue #708, E21). Diese Regel
// benennt das Feld und zeigt auf die Zeile des Eintrags (Plan #753, E18).
function regelCheckStufe(config) {
  const out = [];
  (Array.isArray(config.buildChecks) ? config.buildChecks : []).forEach((check, i) => {
    if (!istObjekt(check) || !("stufe" in check)) return;
    if (CHECK_STUFEN.includes(check.stufe)) return;
    const genannt = typeof check.stufe === "string" ? `'${check.stufe}'` : JSON.stringify(check.stufe);
    const moeglich = CHECK_STUFEN.map((s) => "'" + s + "'").join(", ");
    out.push(befund(`buildChecks[${i}].stufe`, tx("regel.stufeFremd", { genannt, moeglich })));
  });
  return out;
}

// Trägt keine Prüfung die Paketstufe, hat die nächtliche Umsetzung kein Gate: Der Start-Guard des
// Nacht-Runners weist genau diesen Zustand ab (Issue #760). Kein Fehler — die Konfiguration ist
// gültig und soll sich speichern lassen (Plan #753, E18, Befundart aus einstellungen-13). Die
// Oberfläche bearbeitet die Stufe nicht, deshalb nennt die Meldung den Weg in die Datei; sonst
// stünde am Bildschirm ein Mangel, für den es dort keinen Handgriff gibt.
function regelPaketstufeFehlt(config) {
  const checks = Array.isArray(config.buildChecks) ? config.buildChecks : [];
  if (checks.length === 0) return [];
  if (checks.some((check) => stufeVon(check) === CHECK_STUFEN[0])) return [];
  return [befund("buildChecks", tx("regel.paketstufeFehlt"), "warnung")];
}

// --- Die Achse `nichtBeimAbschluss` (Issue #949, Plan #944) ---
//
// Sie ist keine zweite Stufe: Die Stufe sagt, WANN eine Prüfung fällig ist, diese Achse sagt,
// WARUM sie den Abschluss eines einzelnen Arbeitspakets nicht tragen muss. Drei Regeln, und sie
// sind von verschiedener Art — der unbekannte Wert und die Achse an einer späteren Stufe sind
// Fehler, weil `kit/checks.mjs` bei beidem unbedingt abbricht; das leere Abschluss-Gate ist eine
// Warnung, aus demselben Grund wie bei `regelPaketstufeFehlt`.
//
// Die Oberfläche bearbeitet die Achse nicht — dieselbe Behandlung wie die Stufe (Plan #753, E18),
// deshalb nennt jede Meldung den Weg in die Datei.
// SYNC: `NICHT_BEIM_ABSCHLUSS` in kit/checks.mjs und das enum in templates/workflow.config.schema.json.
const ABSCHLUSS_ACHSE = ["zusammenspiel", "volleTestmenge"];


/** Die Einträge von `buildChecks`, die die Achse tragen, mit ihrer Zeilennummer. */
function abschlussTraeger(config) {
  const out = [];
  (Array.isArray(config.buildChecks) ? config.buildChecks : []).forEach((check, i) => {
    if (istObjekt(check) && "nichtBeimAbschluss" in check) out.push({ check, i });
  });
  return out;
}

// SYNC: die Werteliste in kit/checks.mjs, `NICHT_BEIM_ABSCHLUSS` — ein fremder Wert bricht dort
// den Lauf ab. Dieselbe Lage wie bei `regelCheckStufe`: Das Schema-oneOf fängt ihn bereits ab,
// meldet aber nur "passt auf keine der erlaubten Formen" und zeigt nicht auf das Feld.
function regelNichtBeimAbschlussWert(config) {
  const out = [];
  for (const { check, i } of abschlussTraeger(config)) {
    if (ABSCHLUSS_ACHSE.includes(check.nichtBeimAbschluss)) continue;
    const genannt = typeof check.nichtBeimAbschluss === "string" ? `'${check.nichtBeimAbschluss}'` : JSON.stringify(check.nichtBeimAbschluss);
    const moeglich = ABSCHLUSS_ACHSE.map((w) => "'" + w + "'").join(", ");
    out.push(befund(`buildChecks[${i}].nichtBeimAbschluss`, tx("regel.abschlussWert", { genannt, moeglich, datei: tx("regel.abschlussDatei") })));
  }
  return out;
}

// An einem Eintrag der Stufe `push` oder `merge` sagt die Achse nichts: Dort läuft die Prüfung
// beim Abschluss ohnehin nicht, die Stufe hat es schon entschieden. Ein Feld, das nichts bewirkt,
// ist entweder ein Irrtum über die Achse oder ein Rest — beides fällt hier auf und nicht erst der
// nächsten Session, deren Prüflauf daran abbricht.
// SYNC: `pruefeNichtBeimAbschlussStufe` in kit/checks.mjs.
function regelNichtBeimAbschlussStufe(config) {
  const out = [];
  for (const { check, i } of abschlussTraeger(config)) {
    const stufe = stufeVon(check);
    if (stufe === CHECK_STUFEN[0]) continue;
    out.push(befund(`buildChecks[${i}].nichtBeimAbschluss`, tx("regel.abschlussStufe", { stufe, paket: CHECK_STUFEN[0], datei: tx("regel.abschlussDatei") })));
  }
  return out;
}

// Trägt JEDER Eintrag der Paketstufe die Achse oder einen `guete`-Block, lässt ein Abschlusslauf
// alle aus — er wäre grün, weil er nichts gefahren hat, und ein leeres Gate fällt an nichts auf.
// Kein Fehler: Die Konfiguration ist gültig, jeder Lauf ohne `--finish` fährt beide Prüfungen,
// und den Halt setzen der Abschlusslauf in `kit/checks.mjs` und der Start-Guard des Nacht-Runners.
// Dieselbe Befundart und derselbe Grund wie bei der Nachbarregel `regelPaketstufeFehlt`.
//
// Eine Config OHNE Paketstufen-Eintrag fällt hier nicht durch: Sie hatte nie ein Gate, und dazu
// steht die Meldung der Nachbarregel bereit — zwei Meldungen über denselben Zustand wären eine
// zu viel.
// SYNC: `pruefeAbschlussGate` in kit/checks.mjs, der Start-Guard in kit/night.mjs.
function regelAbschlussstufeFehlt(config) {
  const checks = Array.isArray(config.buildChecks) ? config.buildChecks : [];
  const paketstufe = checks.filter((check) => stufeVon(check) === CHECK_STUFEN[0]);
  if (paketstufe.length === 0) return [];
  if (paketstufe.some((check) => !istObjekt(check) || (!check.nichtBeimAbschluss && !istObjekt(check.guete)))) return [];
  return [befund("buildChecks", tx("regel.abschlussFehlt"), "warnung")];
}

// Das Feld `abschlussBereiche` (Issue #1532, Plan #1529, E7): Ein Eintrag mit der Achse nennt
// die Bereiche, bei deren direkter Berührung er beim Abschluss doch läuft. Jede Form, in der das
// Feld nichts bewirken könnte, ist ein Fehler, weil `kit/checks.mjs` beim Start daran abbricht:
// ohne die Achse, keine nicht leere Liste von Namen, ein unbekannter Bereich, ein Bereich außerhalb
// von `areas` (das entfällt bei `always: true` und ohne `areas`, dort wählt jeder Bereich aus).
// Ein unbekannter Name steht nur im zweiten Befund, nicht auch im vierten.
//
// Die Oberfläche bearbeitet das Feld nicht, wie die Achse selbst: Es steht am Eintrag in der Datei,
// `checkSetzen` lässt es stehen, und `bereichsFolgen` zieht Umbenennen und Entfernen nach.
// SYNC: `pruefeAbschlussBereiche` in kit/checks.mjs.
function regelAbschlussBereiche(config) {
  const bekannt = new Set(Object.keys(istObjekt(config.checkAreas) ? config.checkAreas : {}));
  const datei = tx("regel.abschlussDatei");
  const out = [];
  (Array.isArray(config.buildChecks) ? config.buildChecks : []).forEach((check, i) => {
    if (!istObjekt(check) || check.abschlussBereiche === undefined || check.abschlussBereiche === null) return;
    const pfad = `buildChecks[${i}].abschlussBereiche`;
    const liste = check.abschlussBereiche;
    if (!check.nichtBeimAbschluss) out.push(befund(pfad, tx("regel.abschlussBereicheOhneAchse", { datei })));
    if (!Array.isArray(liste) || liste.length === 0 || liste.some((name) => typeof name !== "string")) {
      out.push(befund(pfad, tx("regel.abschlussBereicheForm", { wert: JSON.stringify(liste), datei })));
      return;
    }
    const genannt = (namen) => namen.map((n) => "'" + n + "'").join(", ");
    const fremd = liste.filter((name) => !bekannt.has(name));
    if (fremd.length > 0) out.push(befund(pfad, tx("regel.abschlussBereicheFremd", { genannt: genannt(fremd), datei })));
    if (check.always === true || !Array.isArray(check.areas)) return;
    const ausserhalb = liste.filter((name) => bekannt.has(name) && !check.areas.includes(name));
    if (ausserhalb.length > 0) out.push(befund(pfad, tx("regel.abschlussBereicheAusserhalb", { genannt: genannt(ausserhalb), datei })));
  });
  return out;
}

// --- Die Gütemessung (Issue #764, Plan #753) ---
//
// Vier Regeln, die das Schema nicht ausdrücken kann: "höchstens ein Eintrag" ist eine Aussage
// über die Liste, "nicht zusammen mit stufe merge" eine über zwei Felder, und die Zahl der
// Gruppen eines Musters steht in keinem Schlüsselwort. Dieselben Grenzen bricht `pruefeGuete`
// in kit/checks.mjs zur Laufzeit ab — hier stehen sie vor dem Speichern, damit man sie sieht,
// bevor ein Nachtlauf daran hängt.
//
// Jeder Befund nennt seinen Pfad (Plan #753, E18): Die Oberfläche zeigt den guete-Block an,
// sie bearbeitet ihn nicht, und ein Befund ohne Ort erschiene unbehebbar. Deshalb steht in
// jeder dieser Meldungen auch der Weg in die Datei.
// SYNC: `pruefeGuete` in kit/checks.mjs.

/** Die Einträge von `buildChecks`, die einen `guete`-Block tragen, mit ihrer Zeilennummer. */
function gueteTraeger(config) {
  const out = [];
  (Array.isArray(config.buildChecks) ? config.buildChecks : []).forEach((check, i) => {
    if (istObjekt(check) && istObjekt(check.guete)) out.push({ check, i });
  });
  return out;
}

/**
 * Die Zahl der fangenden Gruppen eines Musters, `null` bei einem Ausdruck, den die
 * Laufzeit nicht übersetzen kann. Das angehängte `|` macht jeden Pfad des Ausdrucks
 * optional: Der Treffer auf dem leeren Text nennt dann für jede Gruppe ein Feld,
 * ohne dass das Muster selbst passen müsste.
 */
function gruppenZahl(muster) {
  try {
    return new RegExp(`${muster}|`).exec("").length - 1;
  } catch {
    return null;
  }
}

function regelGueteMuster(guete, pfad) {
  if (typeof guete.muster !== "string") return []; // den Typ meldet das Schema
  const gruppen = gruppenZahl(guete.muster);
  if (gruppen === null) {
    return [befund(`${pfad}.muster`, tx("regel.gueteKeinAusdruck", { muster: guete.muster, datei: tx("regel.gueteDatei") }))];
  }
  if (gruppen === 1) return [];
  return [befund(`${pfad}.muster`, tx("regel.gueteGruppen", { gruppen, datei: tx("regel.gueteDatei") }))];
}

function regelGueteMarke(guete, pfad) {
  if (typeof guete.marke !== "number" || (guete.marke >= 0 && guete.marke <= 100)) return [];
  return [befund(`${pfad}.marke`, tx("regel.gueteMarke", { marke: guete.marke, datei: tx("regel.gueteDatei") }))];
}

function regelGuete(config) {
  const traeger = gueteTraeger(config);
  const erster = traeger[0];
  const out = [];
  for (const { check, i } of traeger) {
    const pfad = `buildChecks[${i}].guete`;
    if (check !== erster.check) {
      out.push(befund(pfad, tx("regel.gueteZweiter", { erster: `buildChecks[${erster.i}]`, datei: tx("regel.gueteDatei") })));
      continue; // Welche der beiden Messungen gilt, ist offen; ihre Felder zu prüfen hieße, sie schon anzunehmen.
    }
    if (check.stufe === CHECK_STUFEN[2]) {
      out.push(befund(`buildChecks[${i}].stufe`, tx("regel.gueteMerge", { merge: CHECK_STUFEN[2], paket: CHECK_STUFEN[0], push: CHECK_STUFEN[1] })));
    }
    out.push(...regelGueteMarke(check.guete, pfad), ...regelGueteMuster(check.guete, pfad));
  }
  return out;
}

// Das Schema-oneOf fängt eine Stufe mit beiden oder keinem der Felder bereits ab, meldet aber
// nur "passt auf keine der erlaubten Formen" — diese Regel benennt, welches Feld zu viel oder
// zu wenig ist (Issue #708, E21).
function regelStufenFelder(config) {
  const out = [];
  for (const [stufe, eintrag] of Object.entries(istObjekt(config.night?.stufen) ? config.night.stufen : {})) {
    if (!istObjekt(eintrag)) continue;
    const hatModell = "modell" in eintrag;
    const hatKommando = "kommando" in eintrag;
    if (hatModell && hatKommando) out.push(befund(`night.stufen.${stufe}`, tx("regel.stufeBeides")));
    else if (!hatModell && !hatKommando) out.push(befund(`night.stufen.${stufe}`, tx("regel.stufeKeins")));
  }
  return out;
}

// Die Gründlichkeit gehört zu einer Stufe mit `modell` (Issue #845, Plan #843 E2): Sie
// geht als `--effort` an die Claude-CLI, und einem fremden Programm neben `kommando`
// kann das Kit sie nicht setzen. Das Schema weist die Form ab, meldet aber nur "passt
// auf keine der erlaubten Formen" — diese Regel benennt das Feld, das zu viel ist.
const EFFORT_WERTE = ["low", "medium", "high", "xhigh", "max"];

function regelStufenEffort(config) {
  const out = [];
  for (const [stufe, eintrag] of Object.entries(istObjekt(config.night?.stufen) ? config.night.stufen : {})) {
    if (!istObjekt(eintrag) || !("effort" in eintrag)) continue;
    const pfad = `night.stufen.${stufe}.effort`;
    // Steht das Feld an der falschen Stufe, sagt sein Wert nichts mehr aus — ein zweiter
    // Befund zum Wert verdeckte nur, dass das Feld hier überhaupt nicht hingehört.
    if ("kommando" in eintrag) out.push(befund(pfad, tx("regel.effortKommando")));
    else if (!EFFORT_WERTE.includes(eintrag.effort)) out.push(befund(pfad, tx("regel.effortWert", { effort: eintrag.effort, werte: EFFORT_WERTE.join(", ") })));
  }
  return out;
}

// Kopplung an night.modelle (Issue #708, E18) — kann das Schema nicht prüfen.
function regelStufenModell(config) {
  const bekannt = new Set(Array.isArray(config.night?.modelle) ? config.night.modelle : []);
  const out = [];
  for (const [stufe, eintrag] of Object.entries(istObjekt(config.night?.stufen) ? config.night.stufen : {})) {
    if (!istObjekt(eintrag) || typeof eintrag.modell !== "string") continue;
    if (!bekannt.has(eintrag.modell)) out.push(befund(`night.stufen.${stufe}.modell`, tx("regel.modellUnbekannt", { modell: eintrag.modell })));
  }
  return out;
}

// Das Modell des Laufs hängt an derselben Liste (Issue #994): Der Nacht-Runner endet vor
// dem Start, wenn night.modell dort fehlt — die Prüfung sagt es schon beim Speichern.
function regelLaufModell(config) {
  const modell = config.night?.modell;
  if (typeof modell !== "string" || modell === "") return [];
  const bekannt = new Set(Array.isArray(config.night?.modelle) ? config.night.modelle : []);
  return bekannt.has(modell) ? [] : [befund("night.modell", tx("regel.modellUnbekannt", { modell }))];
}

// Die Anteile in aufwand.schwellen brauchen hier keine eigene Regel mehr (Issue #824):
// Seit `minimum`/`maximum` am Feld des Schemas stehen, prüft sie `pruefeSchema` mit
// demselben Pfad. Eine Zusatzregel daneben wäre eine zweite Wahrheit über dieselbe
// Grenze — und die beiden liefen bei der ersten Änderung auseinander.

/** Die Regeln über mehrere Felder, angewandt auf eine (gemischte) Konfiguration. */
export function zusatzregeln(config) {
  if (!istObjekt(config)) return [];
  return [
    ...regelRollenzahl(config), ...regelRollenKatalog(config), ...regelReviewerFelder(config),
    ...regelPaare(config), ...regelBereiche(config),
    ...regelLeereBereiche(config), ...regelCheckStufe(config), ...regelPaketstufeFehlt(config),
    ...regelNichtBeimAbschlussWert(config), ...regelNichtBeimAbschlussStufe(config),
    ...regelAbschlussstufeFehlt(config), ...regelAbschlussBereiche(config),
    ...regelGuete(config), ...regelStufenFelder(config), ...regelStufenModell(config),
    ...regelStufenEffort(config), ...regelLaufModell(config),
  ];
}

// ============================================================
// Rollenkatalog und Reviewer-Wahl (Plan #721 E3, E4, E5)
// ============================================================

/**
 * Die Rollennamen, die eine Prüfstufe kennt — die Oberfläche bietet sie zur Wahl an. Jede
 * Rolle steht mit ihrem Prompt als Datei `kit/rollen/<rolle>.md`.
 *
 * Nachbau statt Import: Diese Datei wird einzeln ausgeliefert und hat keine Nachbardatei.
 * SYNC: die Rollen samt Prompt stehen unter kit/rollen/ — eine neue oder umbenannte Rolle hier nachziehen.
 */
export const ROLLEN_KATALOG = {
  fachlich: ["form-beobachtbarkeit", "abgrenzung"],
  plan: ["architektur-bestand", "schnitt-abhaengigkeiten"],
  issue: ["pruefbarkeit"],
};

/**
 * Löst einen Autor auf einen Reviewer-Namen auf: `/issues` schreibt die volle Modell-ID in
 * den Kontext (`claude-opus-5`), `pairs` und `reviewers[].name` benutzen Kurznamen (`opus`).
 */
function autorNachName(alle, autor) {
  if (!autor) return null;
  const liste = alle || [];
  if (liste.some((r) => r.name === autor)) return autor;
  const perModell = liste.find((r) => r.model && r.model === autor);
  return perModell ? perModell.name : null;
}

/**
 * Wer bei dieser Besetzung wirklich prüft — der Nachbau von `pickReviewers` als reine
 * Funktion, damit die Oberfläche die Wirkung einer Änderung zeigen kann, ohne etwas
 * auszuführen (einstellungen-4).
 *
 * Nachbau statt Aufruf aus derselben Lage wie `mergeWorkflowConfig`: Die Datei wird einzeln
 * ausgeliefert, arbeitet über fremde Projekte mit fremdem Kit-Stand und hat keine
 * Nachbardatei zum Importieren. Gleich gehalten über den `SYNC:`-Kommentar auf beiden Seiten
 * und test/einstellungen-wirkung.test.mjs, das beide Fassungen gegeneinander hält.
 */
// SYNC: das Original ist pickReviewers in kit/board/issue-review.mjs — Änderungen dort nachziehen.
export function waehleReviewer(reviewers, autor, anzahl = 2, pairs = {}) {
  const alle = reviewers || [];
  const aufgeloest = autorNachName(alle, autor);
  const schluessel = aufgeloest ?? autor;
  const gesperrt = new Set([schluessel]);

  const eintrag = pairs?.[schluessel];
  const genannt = Array.isArray(eintrag) ? eintrag.filter((n) => !gesperrt.has(n)) : [];
  if (genannt.length > 0) {
    const gewaehlt = genannt.map((n) => alle.find((r) => r.name === n)).filter(Boolean).slice(0, anzahl);
    return { gewaehlt, unterbesetzt: gewaehlt.length < anzahl, quelle: "pairs", autorAufgeloest: aufgeloest !== null };
  }
  const gewaehlt = alle.filter((r) => !gesperrt.has(r.name)).slice(0, anzahl);
  return { gewaehlt, unterbesetzt: gewaehlt.length < anzahl, quelle: "regel", autorAufgeloest: aufgeloest !== null };
}

/**
 * Der Vorgabewert eines Pfads aus dem eingebetteten Schema, sonst `undefined` — die Quelle
 * der blassen Werte unter einem leeren Feld (Plan #721 E12). Das Schema ist die Quelle, nicht
 * eine zweite Tabelle in der Oberfläche.
 */
export function vorgabeAus(pfad) {
  return schemaFuer(pfad)?.default;
}

/**
 * Eine Namensliste nach Umbenennung und Entfernung: die bleibenden Namen in ihrer Reihenfolge
 * und ob dabei einer herausfiel. `neuerName` und `weg` sind schlichte Objekte, damit die
 * Funktion ohne Map und Set auskommt — sie läuft auch im Browser (siehe `paarungsFolgen`).
 *
 * Der Name nennt keine Paarung, weil die Rechnung zweimal gebraucht wird: für die Prüfer einer
 * Paarungszeile und für die Bereiche eines Prüfkommandos (`bereichsFolgen`). Beides ist eine
 * Liste von Namen, aus der Namen umbenannt und entfernt werden.
 */
function namensliste(liste, neuerName, weg) {
  const bleibt = [];
  let nameWeg = false;
  for (const name of Array.isArray(liste) ? liste : []) {
    if (weg[name] === true) nameWeg = true;
    else bleibt.push(Object.hasOwn(neuerName, name) ? neuerName[name] : name);
  }
  return { bleibt: bleibt, nameWeg: nameWeg };
}

/**
 * Benennt den Schlüssel eines flachen Objekts um und hält dabei die Reihenfolge — die eine
 * Fassung für die Stellen, die einen Namen als Schlüssel führen: die Bereiche aus
 * `checkAreas` (M4) und die Paarungszeilen aus `issueReview.pairs` (M2). Liefert
 * `{ok, grund, objekt}`; bei `ok: false` ist `objekt` der unveränderte Bestand, und der
 * Aufrufer rechnet keine Folge (Issue #816).
 *
 * Ein schon belegter Zielname wird abgelehnt statt zusammengeführt: Zusammenführen ist bei
 * Mustern und Prüfern je eine eigene fachliche Frage, und bis hierher fiel
 * der alte Eintrag dabei still weg — samt seiner Muster. Der Validator kann das nicht
 * sehen, weil jedes Ergebnis für sich gültig ist.
 *
 * Wie `namensliste` kommt die Funktion ohne Map und Set aus: Ihr Quelltext ist zugleich Teil
 * des Bausteins `folgen` des Browser-Skripts, und der Redaktor muss die Ablehnung zeigen,
 * bevor etwas in die Arbeitskopie geht.
 */
export function schluesselUmbenennen(objekt, alt, neu) {
  const bisher = objekt !== null && typeof objekt === "object" && !Array.isArray(objekt) ? objekt : {};
  const hat = function (name) { return Object.hasOwn(bisher, name); };
  if (!hat(alt)) return { ok: false, grund: tx("folgen.gibtEsNicht", { name: alt }), objekt: bisher };
  if (neu !== alt && hat(neu)) {
    return { ok: false, grund: tx("folgen.gibtEsSchon", { name: neu }), objekt: bisher };
  }
  const kopie = {};
  for (const name of Object.keys(bisher)) kopie[name === alt ? neu : name] = bisher[name];
  return { ok: true, grund: null, objekt: kopie };
}

/**
 * Die Folgen einer Umbenennung oder Entfernung in `issueReview.pairs` (Kriterien 8, 9, 9a).
 * Liefert die neuen Paarungen und je betroffener Zeile einen Eintrag für die Rückfrage:
 * `autorzeile` — die eigene Zeile des Entfernten als Autor fällt weg, `name` — aus der Zeile
 * eines anderen Autors wird nur sein Name genommen, `leer` — die Zeile bliebe dadurch ohne
 * Prüfer und fällt mit weg. Eine Umbenennung nimmt niemandem etwas weg und ergibt deshalb
 * keinen Eintrag; sie steht im Fuß, nicht in einer Rückfrage.
 *
 * Die Funktion benutzt nichts aus dieser Datei außer `namensliste`: Der Quelltext beider
 * ist zugleich der Baustein `folgen` des Browser-Skripts (`SEITEN_BAUSTEINE`). Der Redaktor
 * muss die Folgen in der Arbeitskopie zeigen, bevor etwas gespeichert wird — abgeschrieben
 * läge die Fassung, die der Mensch bedient, ungeprüft im Zeichenketten-Literal.
 */
export function paarungsFolgen(pairs, umbenannt, entfernt) {
  const alt = pairs !== null && typeof pairs === "object" && !Array.isArray(pairs) ? pairs : {};
  const neuerName = {};
  for (const u of umbenannt || []) neuerName[u.von] = u.nach;
  const weg = {};
  for (const name of entfernt || []) weg[name] = true;
  const benannt = function (name) { return Object.hasOwn(neuerName, name) ? neuerName[name] : name; };
  const neu = {};
  const betroffen = [];
  for (const autor of Object.keys(alt)) {
    if (weg[autor] === true) {
      betroffen.push({ autor: autor, art: "autorzeile" });
      continue;
    }
    const zeile = namensliste(alt[autor], neuerName, weg);
    if (zeile.nameWeg && zeile.bleibt.length === 0) betroffen.push({ autor: autor, art: "leer" });
    else {
      if (zeile.nameWeg) betroffen.push({ autor: autor, art: "name" });
      neu[benannt(autor)] = zeile.bleibt;
    }
  }
  return { pairs: neu, betroffen: betroffen };
}

/** Die Fassung, die Modul und Browser-Skript teilen — siehe `SEITEN_BAUSTEINE.folgen`. */
const FOLGEN_QUELLE = [namensliste, schluesselUmbenennen, paarungsFolgen].map((f) => f.toString()).join("\n\n");

// ============================================================
// Die drei Formen eines Prüfkommandos (Plan #721, Kriterien 18, 19, 20)
// ============================================================
//
// `buildChecks` kennt drei Formen: den bloßen Kommandostring beziehungsweise ein Objekt nur mit
// `cmd`, `{cmd, always: true}` und `{cmd, areas}`. Die ersten beiden laufen gleich, sagen aber
// Verschiedenes — „noch niemand zugeordnet" gegen „bewusst entschieden". Lesen und Schreiben
// stehen deshalb als zwei Funktionen hier und nicht im Redaktor: Die Formtreue ist eine Regel,
// und eine Regel im Zeichenketten-Literal prüfte kein Test.

/**
 * Die drei Laufarten mit ihrer deutschen Aufschrift, in der Reihenfolge des Entwurfs. Die Seite
 * zeigt die Aufschrift der Projektsprache aus `TEXTE` (`laufart.<kennung>`); ein Test hält die
 * deutsche dort gleich mit dieser.
 */
export const LAUFARTEN = [["offen", "immer (offen)"], ["immer", "immer"], ["bereiche", "bei Bereichen"]];

/**
 * Ein `buildChecks`-Eintrag als Kommando, Laufart und Bereiche. Ein `areas` ohne Eintrag bleibt
 * die Laufart `bereiche` — es wird nie stillschweigend zu `immer` (Kriterium 19). Was die Form
 * nicht trifft, gilt als `offen`; ein unbrauchbarer Wert in der Datei darf nicht werfen, denn
 * seinen Grund nennt ohnehin die Prüfung.
 */
export function checkForm(eintrag) {
  if (typeof eintrag === "string") return { cmd: eintrag, laufart: "offen", areas: [] };
  const o = eintrag !== null && typeof eintrag === "object" && !Array.isArray(eintrag) ? eintrag : {};
  const cmd = typeof o.cmd === "string" ? o.cmd : "";
  if (Array.isArray(o.areas)) return { cmd: cmd, laufart: "bereiche", areas: o.areas.slice() };
  if (o.always === true) return { cmd: cmd, laufart: "immer", areas: [] };
  return { cmd: cmd, laufart: "offen", areas: [] };
}

/**
 * Setzt Kommando, Laufart oder Bereiche einer Zeile — formtreu (Kriterium 18): Eine Zeile,
 * deren Laufart unverändert bleibt, behält ihre Form. Aus einem String wird kein Objekt, und
 * „immer (offen)" bekommt kein `always`. Bleibt inhaltlich alles gleich, kommt derselbe Eintrag
 * zurück — nur so sieht der Schreiber keine Änderung und die Zeile bleibt in der Datei stehen.
 *
 * Ergänzen statt neu bauen (Plan E9): Ein Feld, das die Tabelle nicht zeigt, bleibt stehen —
 * insbesondere `stufe`, `nichtBeimAbschluss` und `abschlussBereiche`. Die Oberfläche prüft sie
 * und nennt sie im Befund am Pfad des Eintrags, sie bearbeitet sie nicht (Plan #753, E18;
 * Issue #949, #1532); gingen sie beim Speichern einer Zeile
 * verloren, fiele die Prüfung stillschweigend auf die Paketstufe zurück und liefe beim
 * Abschluss wieder mit.
 */
export function checkSetzen(eintrag, aenderung) {
  const a = aenderung || {};
  const form = checkForm(eintrag);
  const cmd = a.cmd === undefined ? form.cmd : a.cmd;
  const laufart = a.laufart === undefined ? form.laufart : a.laufart;
  const areas = a.areas === undefined ? form.areas : a.areas;
  if (typeof eintrag === "string" && laufart === "offen") return cmd === eintrag ? eintrag : cmd;
  const alt = eintrag !== null && typeof eintrag === "object" && !Array.isArray(eintrag) ? eintrag : { cmd: form.cmd };
  const neu = { ...alt };
  neu.cmd = cmd;
  if (laufart === "immer") {
    delete neu.areas;
    neu.always = true;
  } else if (laufart === "bereiche") {
    delete neu.always;
    neu.areas = areas.slice();
  } else {
    delete neu.areas;
    delete neu.always;
  }
  if (typeof eintrag !== "string" && JSON.stringify(neu) === JSON.stringify(alt)) return eintrag;
  return neu;
}

/**
 * Die Folgen einer Umbenennung oder Entfernung von Bereichen in `buildChecks` (Kriterium 20).
 * Liefert die neuen Kommandos und je betroffenem Kommando einen Eintrag für die Rückfrage:
 * `name` — nur ein Bereichsname fällt aus seiner Liste, `leer` — das Kommando bliebe ganz ohne
 * Bereich. Dann bleibt `areas` leer stehen: Das hält das Speichern auf (Kriterium 19), und das
 * Kommando wird nie stillschweigend zu „immer". Eine Umbenennung nimmt keinem Kommando etwas
 * weg und ergibt deshalb keinen Eintrag.
 *
 * Wie `paarungsFolgen` benutzt die Funktion nichts aus dieser Datei außer `namensliste`,
 * `checkForm` und `checkSetzen` — ihr Quelltext ist zugleich der Baustein `checkformen` des
 * Browser-Skripts, und der Redaktor muss die Folgen in der Arbeitskopie zeigen, bevor etwas
 * gespeichert wird.
 */
export function bereichsFolgen(buildChecks, umbenannt, entfernt) {
  const alt = Array.isArray(buildChecks) ? buildChecks : [];
  const neuerName = {};
  for (const u of umbenannt || []) neuerName[u.von] = u.nach;
  const weg = {};
  for (const name of entfernt || []) weg[name] = true;
  const neu = [];
  const betroffen = [];
  // `abschlussBereiche` zieht in jeder Laufart mit (Issue #1532): Ohne Bedienelement stünde sonst
  // ein alter Name im Feld, und die Config ließe sich nicht mehr speichern. Bleibt die Liste
  // leer, bleibt sie leer stehen — dann hält der Befund das Speichern auf, wie bei `areas`.
  const abschlussNachziehen = function (eintrag) {
    if (eintrag === null || typeof eintrag !== "object" || !Array.isArray(eintrag.abschlussBereiche)) return eintrag;
    const liste = namensliste(eintrag.abschlussBereiche, neuerName, weg).bleibt;
    if (JSON.stringify(liste) === JSON.stringify(eintrag.abschlussBereiche)) return eintrag;
    return { ...eintrag, abschlussBereiche: liste };
  };
  alt.forEach(function (eintrag, i) {
    const form = checkForm(eintrag);
    if (form.laufart !== "bereiche") {
      neu.push(abschlussNachziehen(eintrag));
      return;
    }
    const zeile = namensliste(form.areas, neuerName, weg);
    if (zeile.nameWeg) betroffen.push({ index: i, cmd: form.cmd, art: zeile.bleibt.length === 0 ? "leer" : "name" });
    neu.push(abschlussNachziehen(checkSetzen(eintrag, { areas: zeile.bleibt })));
  });
  return { buildChecks: neu, betroffen: betroffen };
}

/** Die Fassung, die Modul und Browser-Skript teilen — siehe `SEITEN_BAUSTEINE.checkformen`. */
const CHECK_QUELLE = [checkForm, checkSetzen, bereichsFolgen].map((f) => f.toString()).join("\n\n");

// ============================================================
// Einfache Gruppen (Plan #721 E8, Kriterien 27 und 28)
// ============================================================
//
// Ein flaches Objekt aus einzelnen Werten — `triggers`, `columns`, die Angaben zu Toolbox,
// GitHub und lokalem Tracker. Ein Feld je Eintrag statt eines Textblocks, und dort, wo eine
// persönliche Abweichung erlaubt ist, je Zeile Team-Wert, persönlicher Wert und geltender Wert.
//
// Wie `paarungsFolgen` und `checkSetzen` benutzen die beiden Funktionen nichts aus dieser
// Datei: Ihr Quelltext ist zugleich der Baustein `gruppen` des Browser-Skripts. Der Redaktor
// muss die Zeilen aus der Arbeitskopie rechnen, bevor etwas gespeichert wird — abgeschrieben
// läge die Fassung, die der Mensch bedient, ungeprüft im Zeichenketten-Literal.

/**
 * Die Zeilen einer einfachen Gruppe: je Eigenschaft des Schemas eine, dazu jedes Feld, das
 * eine der beiden Dateien trägt und das Schema nicht kennt (`fremd`). `ausgelassen` nennt die
 * Unterfelder mit eigenem Teil — `toolbox.tokenFile` hat seine eigene Eingabe und stünde hier
 * ein zweites Mal da, ohne persönliche Abweichung.
 *
 * `abweichend` trägt genau die Zeile, die vom Team-Wert abweicht. Weil die persönliche Datei
 * nach Plan E8 das vollständige geltende Objekt trägt, ist das nicht dasselbe wie „steht in
 * der persönlichen Datei": Ändert das Team später ein Feld, von dem niemand abweichen wollte,
 * weicht dessen Zeile danach ab — der alte Wert steht dort eingefroren.
 */
export function gruppenZeilen(pfad, schema, werte, ausgelassen) {
  const w = werte || {};
  const eigen = objektOder(schema?.properties);
  const t = objektOder(w.team);
  const p = objektOder(w.persoenlich);
  const g = objektOder(w.gilt);
  const weg = ausgelassen || [];
  const namen = [];
  for (const feld of Object.keys(eigen).concat(Object.keys(t), Object.keys(p), Object.keys(g))) {
    if (!namen.includes(feld) && !weg.includes(feld)) namen.push(feld);
  }
  return namen.map(function (feld) {
    return {
      feld: feld,
      pfad: pfad + "." + feld,
      schema: eigen[feld] || null,
      fremd: eigen[feld] === undefined,
      team: t[feld],
      persoenlich: w.persoenlich === undefined ? undefined : p[feld],
      gilt: g[feld] === undefined ? t[feld] : g[feld],
      abweichend: w.persoenlich !== undefined && JSON.stringify(p[feld]) !== JSON.stringify(t[feld]),
    };
  });
}

/**
 * Eine persönliche Abweichung an einem Feld einer einfachen Gruppe (Plan #721 E8). Die
 * Oberfläche legt das **vollständige geltende Objekt** ab, weil `mergeWorkflowConfig` ein
 * Allowlist-Feld vollständig ersetzt: Ein persönliches `{push: …}` ließe `go` und `merge`
 * ungesetzt. `basis` ist der Stand, auf den die Änderung trifft — der persönliche Wert, wenn
 * es einen gibt, sonst der geltende.
 *
 * Ein leerer Wert heißt „wie Team" und nimmt die Abweichung dieser Zeile zurück. Weicht danach
 * keine Zeile mehr ab, ist der Eintrag überflüssig: `{ entfernen: true }` — der Weg, auf dem
 * das Zurücksetzen der letzten Abweichung den Eintrag ganz aus der persönlichen Datei nimmt.
 */
export function gruppeSetzen(team, basis, feld, wert) {
  const t = objektOder(team);
  const neu = { ...objektOder(basis) };
  if (wert === undefined || wert === "") {
    if (t[feld] === undefined) delete neu[feld];
    else neu[feld] = t[feld];
  } else {
    neu[feld] = wert;
  }
  const felder = Object.keys(neu).concat(Object.keys(t));
  const weichtAb = felder.some(function (f) { return JSON.stringify(neu[f]) !== JSON.stringify(t[f]); });
  return weichtAb ? { wert: neu } : { entfernen: true };
}

/**
 * Ein Pfad unter den Namen der Projektsprache (Issue #1441). `namen` ist die Tabelle aus
 * kit/board/config-namen.mjs — je Pfad in deutscher Schreibweise der Name seines letzten
 * Glieds —, in einem deutschen Projekt `null`: Dann bleibt der Pfad, wie er ist. Eine
 * Listenposition (`[2]`) bleibt stehen; ein frei gewählter Name, etwa ein Bereich unter
 * `checkAreas`, steht nicht in der Tabelle und bleibt ebenso.
 *
 * Eine Funktionsdeklaration ohne Modulbezug, weil sie per `toString()` auch ins
 * Browser-Skript wandert (`SEITEN_BAUSTEINE.namen`).
 */
export function anzeigePfad(pfad, namen) {
  if (!namen || !pfad) return pfad;
  let tabelle = "";
  return pfad.split(".").map(function (glied) {
    const treffer = /^([^[]*)((?:\[\d*\])*)$/.exec(glied);
    const name = treffer ? treffer[1] : glied;
    const index = treffer ? treffer[2] : "";
    tabelle = tabelle ? tabelle + "." + name : name;
    const uebersetzt = Object.prototype.hasOwnProperty.call(namen, tabelle) ? namen[tabelle] : name;
    tabelle += index.replaceAll(/\[\d*\]/g, "[]");
    return uebersetzt + index;
  }).join(".");
}

/** Die Fassung, die Modul und Browser-Skript teilen — siehe `SEITEN_BAUSTEINE.gruppen`. */
const GRUPPEN_QUELLE = [objektOder, gruppenZeilen, gruppeSetzen].map((f) => f.toString()).join("\n\n");

// ============================================================
// Themen (Plan #674 E14)
// ============================================================

/** Wurzelfeld → Thema. Ein Test verlangt jedes Wurzelfeld des Schemas außer `version`. */
export const THEMEN = {
  buildChecks: "Prüfungen", checkAreas: "Prüfungen", ohnePruefung: "Prüfungen", nurGeruest: "Prüfungen", gekoppelteBereiche: "Prüfungen", testAblagen: "Prüfungen", mutationCommand: "Prüfungen", guetekommandos: "Prüfungen", formatFixCommand: "Prüfungen",
  language: "Board", codeHost: "Board", issueTracker: "Board", provider: "Board", columns: "Board", github: "Board", toolbox: "Board", local: "Board",
  reviewScope: "Review", reviewModel: "Review", reviewCommand: "Review", reviewLesegrenze: "Review", issueReview: "Review", reviewStufen: "Review", befunde: "Review", vorgeschichte: "Review", szenarienAb: "Review", vertragsRepos: "Review",
  pruefLauf: "Review",
  night: "Nachtbetrieb", aufwand: "Nachtbetrieb", wirksamkeit: "Nachtbetrieb",
  mainBranch: "Release", productionBranch: "Release", pushPruefung: "Release", triggers: "Release", installCommand: "Release",
};

// ============================================================
// Teile (Plan #721)
// ============================================================
//
// Nicht mehr das Schema eines Feldes entscheidet über seine Eingabe, sondern der Teil, zu dem
// es gehört. `m1` bis `m7` sind die sieben Teile des verbindlichen Entwurfs
// docs/entwuerfe/einstellungen-ohne-json.html; dazu kommen die generischen Nachbarn `wert`
// (ein Feld für einen einfachen Wert) und `text` (die Anzeige in Dateischreibweise). `m7` ist
// zugleich der generische Teil „Gruppe" für ein flaches Objekt.
//
// `text` ist der Rückfall und trägt das erste Nicht-Ziel der Anforderung #705: Die Modellliste
// der Nacht bleibt, wie sie ist (sie wird mit oder nach #701 umgebaut), und Einstellungen, die
// das Kit nicht kennt, bekommen keine eigene Eingabe.
//
// Bekannte Ausnahme im Rückfall ist `testAblagen` (Issue #1032, Plan #1029 A13): Das Feld
// kennt zwei Eintragsformen — ein Paar aus `quelle` und `test` oder den Marker
// `{ "vorgaben": true }` — und damit keine feste Tabelle, in die eine eigene Eingabe es legen
// könnte. Es bleibt in Dateischreibweise.
// Ebenso `vertragsRepos` (Issue #1614, Plan #1611 E8): eine Liste von Objekten
// `{ name, url, zweig }`, die wie `testAblagen` in Dateischreibweise bearbeitet wird.

/**
 * Wurzelfelder, deren Unterfelder die Teile einzeln bearbeiten. Ein solches Feld erscheint
 * nicht mehr als Ganzes: `projektZustand` zerlegt es in seine Unterfelder, und jedes von ihnen
 * nennt seinen Teil selbst. Trägt die Datei dort etwas anderes als ein Objekt, bleibt das
 * Wurzelfeld ungeteilt und fällt auf den Text-Teil zurück.
 */
const ZERSCHNITTEN = new Set(["issueReview", "night"]);

/**
 * Je Teil eine Kennung, ein Titel, das Thema, die Reihenfolge, die Pfade, die er bearbeitet,
 * und der Name seines Redaktors. Ein Teil ohne eigenes Thema (`thema: null`) ist generisch:
 * Er tritt je Pfad einmal auf und trägt dessen Thema und dessen Pfad als Überschrift. Ein Test
 * verlangt, dass jedes Wurzelfeld des Schemas außer `version` hier einen Ort hat.
 *
 * `folgen` sind Pfade, die ein Teil nicht bearbeitet, aber als Folge einer eigenen Änderung
 * mitschreibt (Kriterium 9a): Einen Reviewer umzubenennen oder zu entfernen ist samt der
 * Folgen in den Paarungen eine Änderung des Reviewer-Teils. Der Fuß nennt sie deshalb mit;
 * bearbeitet wird der Pfad weiter dort, wo er in `pfade` steht.
 */
export const TEILE = [
  { kennung: "m1", titel: "Reviewer", thema: "Review", reihenfolge: 1, redaktor: "reviewer", pfade: ["issueReview.requiredBeforeReady", "issueReview.reviewers"], folgen: ["issueReview.pairs"] },
  { kennung: "m2", titel: "Paarungen", thema: "Review", reihenfolge: 2, redaktor: "paarungen", pfade: ["issueReview.pairs"] },
  { kennung: "m3", titel: "Prüfstufen", thema: "Review", reihenfolge: 3, redaktor: "pruefstufen", pfade: ["reviewStufen"] },
  { kennung: "m10", titel: "Befunde", thema: "Review", reihenfolge: 4, redaktor: "befunde", pfade: ["befunde"] },
  { kennung: "m4", titel: "Prüfkommandos und Bereiche", thema: "Prüfungen", reihenfolge: 1, redaktor: "pruefkommandos", pfade: ["buildChecks", "checkAreas", "ohnePruefung", "nurGeruest", "gekoppelteBereiche"] },
  { kennung: "m6", titel: "Nacht-Kette", thema: "Nachtbetrieb", reihenfolge: 1, redaktor: "nachtkette", pfade: ["night.kette", "night.zielUmsetzungMin", "night.festgefahrenNach", "night.stand"] },
  { kennung: "m8", titel: "Aufwand", thema: "Nachtbetrieb", reihenfolge: 2, redaktor: "aufwand", pfade: ["aufwand"] },
  { kennung: "m9", titel: "Wirksamkeit", thema: "Nachtbetrieb", reihenfolge: 3, redaktor: "wirksamkeit", pfade: ["wirksamkeit"] },
  { kennung: "m11", titel: "Aufgabenstufen", thema: "Nachtbetrieb", reihenfolge: 4, redaktor: "stufen", pfade: ["night.stufen"] },
  { kennung: "m7", titel: null, thema: null, reihenfolge: 5, redaktor: "gruppe", pfade: ["triggers", "columns", "github", "toolbox", "local", "pruefLauf"] },
  {
    kennung: "wert", titel: null, thema: null, reihenfolge: 6, redaktor: "wert",
    pfade: ["language", "codeHost", "issueTracker", "provider", "mutationCommand", "guetekommandos", "formatFixCommand", "installCommand", "mainBranch", "productionBranch", "reviewScope", "reviewModel", "reviewCommand", "reviewLesegrenze", "toolbox.tokenFile", "night.modell", "vorgeschichte", "szenarienAb"],
  },
  { kennung: "text", titel: null, thema: null, reihenfolge: 9, redaktor: "text", pfade: ["night.modelle", "night.stufenRegel", "testAblagen", "pushPruefung", "vertragsRepos"] },
];

const TEIL_TEXT = TEILE.find((t) => t.kennung === "text");

/**
 * Je einfacher Gruppe die Unterfelder, die ein Teil ausdrücklich selbst bearbeitet — die
 * Gruppe führt sie nicht. Heute ist das `toolbox.tokenFile`: Es steht in der Allowlist und hat
 * deshalb eine eigene Eingabe mit Team- und persönlicher Ebene. In der Gruppe `toolbox`, die
 * teamweit gilt, stünde es ein zweites Mal da — und dort ohne persönliche Abweichung.
 */
export const GRUPPEN_AUSNAHMEN = Object.fromEntries(
  TEILE.filter((t) => t.redaktor === "gruppe").flatMap((t) => t.pfade).map((pfad) => [
    pfad,
    TEILE.flatMap((t) => t.pfade).filter((p) => p.startsWith(`${pfad}.`)).map((p) => p.slice(pfad.length + 1)),
  ]),
);

/** Der Teil, der einen Pfad bearbeitet. Was kein Teil nennt, fällt auf den Text-Teil zurück. */
export function teilFuer(pfad) {
  return TEILE.find((t) => t.pfade.includes(pfad)) ?? TEIL_TEXT;
}

// ============================================================
// Team- und persönliche Ebene (Plan #674 E6)
// ============================================================
//
// Die heruntergeladene Datei hat keine Nachbardatei board.mjs, aus der sie importieren
// könnte — darum eine dritte Kopie. test/ablauf-workflow-config-merge.test.mjs hält alle drei gleich.

// SYNC: dieselbe Liste in kit/board/grundlagen.mjs und kit/night/grundlagen.mjs — Änderungen dort nachziehen.
const LOCAL_OVERRIDE_ALLOWLIST = ["reviewModel", "reviewCommand", "reviewLesegrenze", "reviewScope", "triggers", "toolbox.tokenFile"];

// Das Paar ist eine Gruppe (Issue #1379, Plan #1375 E11): {reviewModel} ↔ {reviewCommand,
// reviewLesegrenze}; eine Lesegrenze allein verdrängt reviewModel nicht.
// SYNC: dieselbe Zuordnung in kit/board/grundlagen.mjs und kit/night/grundlagen.mjs.
const REVIEWER_PAAR = { reviewModel: ["reviewCommand", "reviewLesegrenze"], reviewCommand: ["reviewModel"] };

// SYNC: strukturgleich zu zerlegeAllowlist in kit/board/grundlagen.mjs und kit/night/grundlagen.mjs.
function zerlegeAllowlist(allowlist) {
  const erlaubteBlaetter = new Map();
  const erlaubteFelder = new Set();
  for (const pfad of allowlist) {
    const [kopf, blatt] = pfad.split(".");
    if (blatt) {
      if (!erlaubteBlaetter.has(kopf)) erlaubteBlaetter.set(kopf, new Set());
      erlaubteBlaetter.get(kopf).add(blatt);
    } else {
      erlaubteFelder.add(kopf);
    }
  }
  return { erlaubteFelder, erlaubteBlaetter };
}

// SYNC: strukturgleich zu setzePersoenlichesFeld in kit/board/grundlagen.mjs — beim Reviewer-Paar
// weicht das Gegenstück, sofern die persönliche Datei es nicht selbst nennt.
function setzePersoenlichesFeld(config, feld, wert, local) {
  config[feld] = wert;
  for (const gegenstueck of REVIEWER_PAAR[feld] ?? []) {
    if (!(gegenstueck in local)) delete config[gegenstueck];
  }
}

// SYNC: strukturgleich zu mergeWorkflowConfig in kit/board/grundlagen.mjs — beide Dateien
// werden vor dem Mischen auf die deutschen Namen gebracht (Issue #1437, Plan #1420 E10).
export function mergeWorkflowConfig(sharedRoh, localRoh) {
  const { config: shared, hinweise } = normalisiereConfig(sharedRoh);
  const config = { ...shared };
  const ignored = [];
  if (!localRoh) return { config, ignored, hinweise };
  const { config: local, hinweise: lokaleHinweise } = normalisiereConfig(localRoh, { sprache: shared.language ?? shared.sprache });
  hinweise.push(...lokaleHinweise);
  const { erlaubteFelder, erlaubteBlaetter } = zerlegeAllowlist(LOCAL_OVERRIDE_ALLOWLIST);
  for (const [feld, wert] of Object.entries(local)) {
    if (erlaubteFelder.has(feld)) {
      setzePersoenlichesFeld(config, feld, wert, local);
    } else if (erlaubteBlaetter.has(feld) && istObjekt(wert)) {
      const blaetter = erlaubteBlaetter.get(feld);
      const zusammen = { ...config[feld] };
      for (const [unterfeld, unterwert] of Object.entries(wert)) {
        if (blaetter.has(unterfeld)) zusammen[unterfeld] = unterwert;
        else ignored.push(`${feld}.${unterfeld}`);
      }
      config[feld] = zusammen;
    } else {
      ignored.push(feld);
    }
  }
  return { config, ignored, hinweise };
}

/** Ob ein Pfad persönlich abweichen darf. */
export function persoenlichErlaubt(pfad) {
  return LOCAL_OVERRIDE_ALLOWLIST.includes(pfad);
}

function lies(objekt, pfad) {
  return pfad.split(".").reduce((k, teil) => (istObjekt(k) ? k[teil] : undefined), objekt);
}

function setze(objekt, pfad, wert) {
  const teile = pfad.split(".");
  let k = objekt;
  for (const teil of teile.slice(0, -1)) {
    if (!istObjekt(k[teil])) k[teil] = {};
    k = k[teil];
  }
  k[teile.at(-1)] = wert;
}

function entferne(objekt, pfad) {
  const [kopf, blatt] = pfad.split(".");
  if (!blatt) return delete objekt[kopf];
  if (!istObjekt(objekt[kopf])) return;
  delete objekt[kopf][blatt];
  if (Object.keys(objekt[kopf]).length === 0) delete objekt[kopf];
}

/**
 * Ein zerschnittenes Wurzelfeld zerfällt in seine Unterfelder — die des Schemas und die, die
 * eine der Dateien trägt. Jedes andere Feld bleibt, wie es ist; ebenso ein zerschnittenes,
 * das irgendwo kein Objekt ist, denn sein Wert soll unverändert lesbar bleiben.
 */
function zerschneide(pfad, werte) {
  if (!ZERSCHNITTEN.has(pfad)) return [pfad];
  if (werte.some((w) => w !== undefined && !istObjekt(w))) return [pfad];
  const felder = new Set([...Object.keys(schemaFuer(pfad)?.properties ?? {}), ...werte.flatMap((w) => (istObjekt(w) ? Object.keys(w) : []))]);
  return [...felder].map((f) => `${pfad}.${f}`);
}

/**
 * Je Einstellung Teamwert, persönliche Abweichung und geltender Wert. Schlüssel sind die
 * Wurzelfelder aus Schema, Team- und persönlicher Datei sowie die Blätter der Allowlist —
 * ein zerschnittenes Wurzelfeld steht dabei mit seinen Unterfeldern statt als Ganzes da.
 */
export function ebenen(team, lokal) {
  const { config } = mergeWorkflowConfig(team ?? {}, lokal ?? null);
  const wurzeln = new Set([
    ...Object.keys(SCHEMA.properties ?? {}).filter((f) => f !== "version"),
    ...Object.keys(team ?? {}),
    ...Object.keys(lokal ?? {}).filter((f) => !f.includes(".") && !LOCAL_OVERRIDE_ALLOWLIST.some((p) => p.startsWith(`${f}.`))),
    ...LOCAL_OVERRIDE_ALLOWLIST,
  ]);
  const pfade = new Set([...wurzeln].flatMap((p) => zerschneide(p, [lies(team ?? {}, p), lies(lokal ?? {}, p), lies(config, p)])));
  const out = {};
  for (const pfad of pfade) {
    out[pfad] = { team: lies(team ?? {}, pfad), persoenlich: lies(lokal ?? {}, pfad), gilt: lies(config, pfad), persoenlichErlaubt: persoenlichErlaubt(pfad) };
  }
  return out;
}

const tiefeKopie = (w) => (w === undefined ? undefined : structuredClone(w));

/**
 * Wendet Änderungen auf der gewählten Ebene an. Liefert `{ ok: true, team, lokal }` mit
 * neuen Objekten oder `{ ok: false, grund }`. Persönlich geht nur, was die Allowlist
 * erlaubt; `entfernt` nimmt persönliche Abweichungen zurück, danach gilt der Teamwert.
 */
export function aenderungAnwenden(team, lokal, { ebene, aenderungen = [], entfernt = [] }) {
  const neuTeam = tiefeKopie(team ?? {});
  const neuLokal = tiefeKopie(lokal ?? {});
  if (ebene !== "team" && ebene !== "persoenlich") return { ok: false, grund: tx("ebene.unbekannt", { ebene }) };
  const ziel = ebene === "team" ? neuTeam : neuLokal;
  for (const { pfad, wert } of aenderungen) {
    if (ebene === "persoenlich" && !persoenlichErlaubt(pfad)) {
      return { ok: false, grund: tx("ebene.nurTeam", { pfad }) };
    }
    setze(ziel, pfad, tiefeKopie(wert));
  }
  for (const pfad of entfernt) entferne(neuLokal, pfad);
  return { ok: true, team: neuTeam, lokal: neuLokal };
}

/**
 * Prüft die gemischte Konfiguration: Schema und Regeln über mehrere Felder. `aenderungen`
 * werden vorher auf `ebene` angewandt — so trägt ein gespeicherter ungültiger Wert
 * denselben Grund wie eine Änderung auf ihn.
 */
export function pruefe(team, lokal, aenderungen = [], ebene = "team") {
  const angewandt = aenderungAnwenden(team, lokal, { ebene, aenderungen });
  if (!angewandt.ok) return [befund(aenderungen[0]?.pfad ?? "", angewandt.grund)];
  const { config } = mergeWorkflowConfig(angewandt.team, angewandt.lokal);
  return [...pruefeSchema(config), ...zusatzregeln(config)];
}

// ============================================================
// Schreiber mit minimalem Diff (Plan #674 E7)
// ============================================================
//
// JSON.stringify schriebe jede Datei neu formatiert; wer danach `git diff` liest, sähe eine
// umgebaute Datei statt der einen geänderten Zeile. Deshalb wird der Text zerlegt und nur an
// den Stellen ersetzt, deren Wert sich geändert hat. Einfache Werte behalten ihre Zeile, Listen
// und Objekte, die sich ändern, werden als ganzer Wertebereich neu geschrieben — elementweises
// Erhalten innerhalb einer Liste kostete einen Diff-Algorithmus ohne fachlichen Nutzen.

/** Leser über einem JSON-Text mit Positionszeiger. */
class JsonLeser {
  constructor(text) { this.text = text; this.i = 0; }

  leer() {
    while (/\s/.test(this.text[this.i] ?? "")) this.i++;
  }

  zeichenkette() {
    const start = this.i++;
    while (this.text[this.i] !== '"') this.i += this.text[this.i] === "\\" ? 2 : 1;
    this.i++;
    return { start, ende: this.i };
  }

  wert() {
    this.leer();
    const start = this.i;
    const zeichen = this.text[this.i];
    if (zeichen === "{") return this.objekt(start);
    if (zeichen === "[") return this.liste(start);
    if (zeichen === '"') return { typ: "wert", ...this.zeichenkette() };
    while (this.i < this.text.length && !/[\s,\]}]/.test(this.text[this.i])) this.i++;
    return { typ: "wert", start, ende: this.i };
  }

  /** Überspringt ein Komma samt Leerraum hinter einem Element. */
  trenner() {
    this.leer();
    if (this.text[this.i] === ",") this.i++;
    this.leer();
  }

  objekt(start) {
    this.i++;
    const glieder = [];
    this.leer();
    while (this.text[this.i] !== "}") {
      const schluessel = this.zeichenkette();
      this.leer();
      this.i++; // ':'
      const kind = this.wert();
      glieder.push({ name: JSON.parse(this.text.slice(schluessel.start, schluessel.ende)), start: schluessel.start, kind });
      this.trenner();
    }
    this.i++;
    return { typ: "objekt", start, ende: this.i, glieder };
  }

  liste(start) {
    this.i++;
    this.leer();
    while (this.text[this.i] !== "]") {
      this.wert();
      this.trenner();
    }
    this.i++;
    return { typ: "liste", start, ende: this.i };
  }
}

/** Zerlegt JSON in Knoten mit Positionen. Die Datei ist vorher mit JSON.parse geprüft. */
function zerlege(text) {
  return new JsonLeser(text).wert();
}

const gleich = (a, b) => JSON.stringify(a) === JSON.stringify(b);

/** Die Einrückung der Zeile, in der `pos` steht. */
function einrueckungAn(text, pos) {
  const zeilenanfang = text.lastIndexOf("\n", pos - 1) + 1;
  return text.slice(zeilenanfang).match(/^[ \t]*/)[0];
}

/** Die Einrückungseinheit der Datei: die erste eingerückte Zeile, sonst zwei Leerzeichen. */
function einheitVon(text) {
  return text.match(/\n([ \t]+)\S/)?.[1] ?? "  ";
}

function serialisiere(wert, einzug, einheit) {
  return JSON.stringify(wert, null, einheit).replaceAll("\n", `\n${einzug}`);
}

/** Die Ersetzungen für einen geänderten Wert an einem Glied. */
function wertAendern(text, glied, altWert, neuWert, einheit, out) {
  if (istObjekt(altWert) && istObjekt(neuWert) && glied.kind.typ === "objekt") {
    objektAendern(text, glied.kind, altWert, neuWert, einheit, out);
    return;
  }
  out.push({ start: glied.kind.start, ende: glied.kind.ende, text: serialisiere(neuWert, einrueckungAn(text, glied.start), einheit) });
}

/**
 * Entfernt zusammenhängende Läufe entfernter Glieder samt Komma. Steht nach einem Lauf ein
 * bleibendes Glied, reicht der Schnitt bis zu dessen Anfang; endet das Objekt mit dem Lauf,
 * beginnt er hinter dem letzten bleibenden Wert. So überlappen sich keine zwei Schnitte.
 */
function laeufeEntfernen(knoten, entfernt, out) {
  const g = knoten.glieder;
  let i = 0;
  while (i < g.length) {
    if (!entfernt.has(i)) { i++; continue; }
    let j = i;
    while (j + 1 < g.length && entfernt.has(j + 1)) j++;
    if (j + 1 < g.length) out.push({ start: g[i].start, ende: g[j + 1].start, text: "" });
    else out.push({ start: i > 0 ? g[i - 1].kind.ende : knoten.start + 1, ende: g[j].kind.ende, text: "" });
    i = j + 1;
  }
}

function gliederAnhaengen(text, knoten, neue, einheit, out) {
  if (neue.length === 0) return;
  const letztes = knoten.glieder.at(-1);
  if (letztes) {
    const einzug = einrueckungAn(text, letztes.start);
    const zeilen = neue.map(([name, w]) => `,\n${einzug}${JSON.stringify(name)}: ${serialisiere(w, einzug, einheit)}`).join("");
    out.push({ start: letztes.kind.ende, ende: letztes.kind.ende, text: zeilen });
    return;
  }
  const aussen = einrueckungAn(text, knoten.start);
  const einzug = aussen + einheit;
  const zeilen = neue.map(([name, w]) => `${einzug}${JSON.stringify(name)}: ${serialisiere(w, einzug, einheit)}`).join(",\n");
  out.push({ start: knoten.start + 1, ende: knoten.ende - 1, text: `\n${zeilen}\n${aussen}` });
}

function objektAendern(text, knoten, alt, neu, einheit, out) {
  const entfernt = new Set();
  knoten.glieder.forEach((glied, index) => {
    if (!(glied.name in neu)) entfernt.add(index);
    else if (!gleich(alt[glied.name], neu[glied.name])) wertAendern(text, glied, alt[glied.name], neu[glied.name], einheit, out);
  });
  const neue = Object.entries(neu).filter(([name]) => !(name in alt));
  const bleibend = knoten.glieder.filter((_, i) => !entfernt.has(i));
  if (bleibend.length === 0 && knoten.glieder.length > 0) {
    // Alles weg: den Innenraum ersetzen — leer, oder durch die neuen Glieder.
    if (neue.length === 0) out.push({ start: knoten.start + 1, ende: knoten.ende - 1, text: "" });
    else gliederAnhaengen(text, { ...knoten, glieder: [] }, neue, einheit, out);
    return;
  }
  laeufeEntfernen(knoten, entfernt, out);
  gliederAnhaengen(text, { ...knoten, glieder: bleibend }, neue, einheit, out);
}

/**
 * Schreibt `neu` in den JSON-Text `alt` und ändert dabei nur, was sich geändert hat.
 * Eine unveränderte Datei bleibt bytegleich.
 */
export function schreibeJson(alt, neu) {
  const altWert = JSON.parse(alt);
  if (gleich(altWert, neu)) return alt;
  const wurzel = zerlege(alt);
  const einheit = einheitVon(alt);
  const out = [];
  if (wurzel.typ === "objekt" && istObjekt(neu) && istObjekt(altWert)) {
    objektAendern(alt, wurzel, altWert, neu, einheit, out);
  } else {
    out.push({ start: wurzel.start, ende: wurzel.ende, text: JSON.stringify(neu, null, einheit) });
  }
  let text = alt;
  for (const e of out.toSorted((a, b) => b.start - a.start || b.ende - a.ende)) {
    text = text.slice(0, e.start) + e.text + text.slice(e.ende);
  }
  return text;
}

// ============================================================
// Projekte und Kit-Stand (Plan #674 E9, E10)
// ============================================================

const KONFIG = join(".claude", "workflow.config.json");
const KONFIG_LOKAL = join(".claude", "workflow.config.local.json");
const STAND_RE = /const KIT_VERSION = "(\d+\.\d+\.\d+)";/;

/** Vergleicht zwei Versionen je Stelle numerisch; `1.9.0` ist älter als `1.53.1`. */
export function vergleicheVersion(a, b) {
  const x = a.split(".").map(Number);
  const y = b.split(".").map(Number);
  for (let i = 0; i < 3; i++) {
    if (x[i] !== y[i]) return x[i] - y[i];
  }
  return 0;
}

function standAus(datei) {
  try {
    return readFileSync(datei, "utf-8").match(STAND_RE)?.[1] ?? null;
  } catch {
    return null;
  }
}

/** Der Startordner und seine direkten Unterverzeichnisse mit Config, je Name einmal. */
export function findeProjekte(ordner) {
  const kandidaten = [ordner];
  for (const eintrag of readdirSync(ordner, { withFileTypes: true })) {
    if (eintrag.isDirectory()) kandidaten.push(join(ordner, eintrag.name));
  }
  const gesehen = new Set();
  const out = [];
  for (const pfad of kandidaten) {
    const name = basename(pfad);
    if (gesehen.has(name) || !existsSync(join(pfad, KONFIG))) continue;
    gesehen.add(name);
    out.push({ name, pfad });
  }
  return out;
}

function kitStandVon(projektPfad, home) {
  return standAus(join(projektPfad, ".claude", "kit", "board.mjs")) ?? standAus(join(home, ".claude", "kit", "board.mjs"));
}

function standUrteil(kitStand, eigenerStand) {
  if (kitStand === null) return { bearbeitbar: false, hinweis: tx("stand.unbekannt") };
  if (vergleicheVersion(kitStand, eigenerStand) > 0) {
    return { bearbeitbar: false, hinweis: tx("stand.neuer", { kit: kitStand, eigen: eigenerStand }) };
  }
  return { bearbeitbar: true, hinweis: null };
}

const hashVon = (text) => (text === null ? null : createHash("sha256").update(text).digest("hex"));

function lesDatei(pfad) {
  return existsSync(pfad) ? readFileSync(pfad, "utf-8") : null;
}

/** Ein Dateiinhalt als Objekt; `null` ohne Datei, `undefined` wenn nicht lesbar. */
function alsObjekt(text, name, hinweise) {
  if (text === null) return null;
  try {
    const wert = JSON.parse(text);
    if (istObjekt(wert)) return wert;
    hinweise.push(tx("datei.keinObjekt", { name }));
  } catch (e) {
    hinweise.push(tx("datei.nichtLesbar", { name, grund: e.message }));
  }
  return undefined;
}

/** Eine gelesene Datei unter den deutschen Namen, mit denen die Oberfläche arbeitet (Plan #1420 E9). */
const deutsch = (roh, sprache) => (istObjekt(roh) ? normalisiereConfig(roh, { sprache }).config : roh);

/**
 * Liest beide Dateien eines Projekts samt Hash und Lesbarkeit. `team` und `lokal` tragen die
 * deutschen Namen, `teamRoh` und `lokalRoh` die Schreibweise der Datei (Issue #1441).
 */
function projektDateien(projekt) {
  const teamText = lesDatei(join(projekt.pfad, KONFIG));
  const lokalText = lesDatei(join(projekt.pfad, KONFIG_LOKAL));
  const hinweise = [];
  const teamRoh = alsObjekt(teamText, KONFIG, hinweise);
  const lokalRoh = alsObjekt(lokalText, KONFIG_LOKAL, hinweise);
  const sprache = spracheAus(teamRoh).wert;
  return {
    teamText, lokalText, teamRoh, lokalRoh, sprache, hinweise,
    team: deutsch(teamRoh), lokal: deutsch(lokalRoh, sprache),
    hashes: { team: hashVon(teamText), lokal: hashVon(lokalText) },
  };
}

/** Das Teilschema eines Pfads aus dem eingebetteten Schema. */
function schemaFuer(pfad) {
  return pfad.split(".").reduce((k, teil) => k?.properties?.[teil], SCHEMA) ?? null;
}

const gehoertZu = (befundPfad, pfad) => befundPfad === pfad || befundPfad.startsWith(`${pfad}.`) || befundPfad.startsWith(`${pfad}[`);

/**
 * Die Projektsprache, nur zur Anzeige (Plan #1420 E2, E12): `language`, sonst der deutsche
 * Altname `sprache`, sonst `de`. Liest die Config selbst statt über kit/board/namen.mjs, weil
 * diese Datei allein verteilt wird. Umgestellt wird über den Installer, nicht hier.
 */
export function spracheAus(team) {
  const gesetzt = istObjekt(team) ? team.language ?? team.sprache : undefined;
  const wert = gesetzt === "en" ? "en" : "de";
  return { wert, anzeige: wert === "en" ? "English" : "Deutsch", umstellung: `node install.mjs --language ${wert === "en" ? "de" : "en"}` };
}

/**
 * Das Teilschema eines Pfads mit den Beschreibungen der Projektsprache (Issue #1441): In
 * einem englischen Projekt stehen dort die Texte aus tools/config-referenz.en.json, je Pfad
 * in derselben Schreibweise (`buildChecks[].stufe`). Ohne englischen Text bleibt der deutsche.
 */
function beschriebenIn(schema, pfad, sprache) {
  if (sprache !== "en" || !istObjekt(schema)) return schema;
  const neu = { ...schema };
  const text = REFERENZ_EN[pfad]?.text;
  if (text) neu.description = text;
  if (istObjekt(schema.properties)) {
    neu.properties = Object.fromEntries(Object.entries(schema.properties).map(([k, s]) => [k, beschriebenIn(s, `${pfad}.${k}`, sprache)]));
  }
  if (istObjekt(schema.items)) neu.items = beschriebenIn(schema.items, `${pfad}[]`, sprache);
  if (Array.isArray(schema.oneOf)) neu.oneOf = schema.oneOf.map((s) => beschriebenIn(s, pfad, sprache));
  return neu;
}

/**
 * Die Sprache, in der ein Projekt angesprochen wird (Issue #1456): die seiner Team-Config, und
 * wo die nicht lesbar ist, die gerade geltende — beim Server die Startsprache.
 */
function spracheVon(projekt) {
  try {
    return spracheAus(JSON.parse(readFileSync(join(projekt.pfad, KONFIG), "utf-8"))).wert;
  } catch {
    return prozessSprache();
  }
}

/**
 * Die Sprache der Seite, bevor ein Projekt offen ist, und der Antworten ohne Projekt: die des
 * Ordners, wenn er selbst ein Projekt ist, sonst die gemeinsame aller Projekte darin, sonst
 * die des Arbeitsverzeichnisses.
 */
function startSprache(ordner) {
  const projekte = findeProjekte(ordner);
  const eigenes = projekte.find((p) => resolve(p.pfad) === resolve(ordner));
  if (eigenes) return spracheVon(eigenes);
  const sprachen = new Set(projekte.map(spracheVon));
  return sprachen.size === 1 ? [...sprachen][0] : prozessSprache();
}

/**
 * Der Zustand eines Projekts, wie die Oberfläche ihn zeigt — in der Sprache des Projekts.
 * `sprache` sagt der Seite, in welcher sie es zeigt.
 */
export function projektZustand(projekt, optionen) {
  return inSprache(spracheVon(projekt), () => zustandIn(projekt, optionen));
}

/** Ein Teil, wie der Zustand ihn trägt — der Titel in der Sprache des Prozesses. */
function teilInstanz(teil) {
  return { kennung: teil.kennung, titel: teil.titel === null ? null : tx(`teil.${teil.kennung}`), redaktor: teil.redaktor, reihenfolge: teil.reihenfolge, eintraege: [] };
}

function zustandIn(projekt, { home, eigenerStand }) {
  const kitStand = kitStandVon(projekt.pfad, home);
  const urteil = standUrteil(kitStand, eigenerStand);
  const d = projektDateien(projekt);
  const lesbar = d.team !== undefined && d.lokal !== undefined;
  const zustand = {
    name: projekt.name,
    sprache: prozessSprache(),
    kitStand,
    bearbeitbar: urteil.bearbeitbar && lesbar,
    hinweise: [...d.hinweise, ...(urteil.hinweis ? [urteil.hinweis] : [])],
    hashes: d.hashes,
    aelterAlsOberflaeche: kitStand !== null && vergleicheVersion(kitStand, eigenerStand) < 0,
    themen: {},
  };
  if (!lesbar) return zustand;
  const sprache = spracheAus(d.teamRoh);
  // Die Namen der Projektsprache für die Seite; ein deutsches Projekt braucht keine (Issue #1441).
  zustand.grundlagen = { sprache, namen: sprache.wert === "en" ? { ...SCHLUESSEL } : null };
  const befunde = pruefe(d.team, d.lokal);
  const instanzen = new Map();
  for (const [pfad, werte] of Object.entries(ebenen(d.team, d.lokal))) {
    const teil = teilFuer(pfad);
    const thema = teil.thema ?? THEMEN[pfad.split(".")[0]] ?? "Unbekannt";
    // Das Thema bleibt Schlüssel unter seinem deutschen Namen; die Seite zeigt es übersetzt.
    const schema = beschriebenIn(schemaFuer(pfad), pfad, sprache.wert);
    // Ein generischer Teil (ohne eigenes Thema) tritt je Pfad einmal auf, ein Teil des
    // Entwurfs einmal je Thema und sammelt seine Pfade.
    const schluessel = teil.thema === null ? `${thema}|${teil.kennung}|${pfad}` : `${thema}|${teil.kennung}`;
    let instanz = instanzen.get(schluessel);
    if (!instanz) {
      instanz = teilInstanz(teil);
      instanzen.set(schluessel, instanz);
      zustand.themen[thema] ??= [];
      zustand.themen[thema].push(instanz);
    }
    // reviewStufen hat keinen Schema-`default` fuer den ganzen Block — der Vorgabewert kommt
    // hier von REVIEW_STUFEN_VORGABE, der Bestandsvorgabe einer Config ohne diesen Block.
    instanz.eintraege.push({
      pfad, beschreibung: schema?.description ?? null, schema, ...werte,
      vorgabe: pfad === "reviewStufen" ? REVIEW_STUFEN_VORGABE : vorgabeAus(pfad),
      befunde: befunde.filter((b) => gehoertZu(b.pfad, pfad)),
    });
  }
  for (const teile of Object.values(zustand.themen)) teile.sort((a, b) => a.reihenfolge - b.reihenfolge);
  return zustand;
}

// ============================================================
// Speichern (Plan #674 E8, E11)
// ============================================================

/** Die Schutzfunktionen, deren Abschalten eine Bestätigung verlangt (Fachplan #671, Frage 10). */
function abgeschaltet(vorher, nachher) {
  const out = [];
  const checks = (c) => (Array.isArray(c?.buildChecks) ? c.buildChecks.length : 0);
  if (checks(vorher) > 0 && checks(nachher) === 0) {
    out.push({ pfad: "buildChecks", text: tx("schutz.checks") });
  }
  if (vorher?.issueReview?.requiredBeforeReady === true && nachher?.issueReview?.requiredBeforeReady !== true) {
    out.push({ pfad: "issueReview.requiredBeforeReady", text: tx("schutz.review") });
  }
  return out;
}

const schluesselVon = (b) => `${b.pfad}|${b.grund}`;

/**
 * Schreibt den neuen Stand unter den Namen der Datei zurück (Issue #1441): Was dort schon
 * steht, behält seinen Namen, auch einen in der anderen Sprache; Neues bekommt den Namen der
 * Projektsprache.
 */
function schreibeProjekt(projekt, d, neu) {
  const team = benenneWieVorlage(neu.team, d.teamRoh, d.sprache);
  const lokal = benenneWieVorlage(neu.lokal, d.lokalRoh, d.sprache);
  if (JSON.stringify(team) !== JSON.stringify(d.teamRoh)) {
    writeFileSync(join(projekt.pfad, KONFIG), schreibeJson(d.teamText, team), "utf-8");
  }
  if (JSON.stringify(lokal) !== JSON.stringify(d.lokalRoh ?? {})) {
    const text = d.lokalText === null ? `${JSON.stringify(lokal, null, 2)}\n` : schreibeJson(d.lokalText, lokal);
    writeFileSync(join(projekt.pfad, KONFIG_LOKAL), text, "utf-8");
  }
}

/**
 * Speichert eine Änderung. Liefert `{ status, body }`: 409 bei geänderter Datei, fehlender
 * Bestätigung oder nicht bearbeitbarem Projekt, 422 bei ungültigem Wert, 200 mit dem neuen
 * Zustand. Ein Wert, der schon vorher ungültig in der Datei stand, hält das Speichern
 * anderer Felder nicht auf.
 */
export function speichere(projekt, auftrag, optionen) {
  return inSprache(spracheVon(projekt), () => speichereIn(projekt, auftrag, optionen));
}

function speichereIn(projekt, auftrag, optionen) {
  const zustand = projektZustand(projekt, optionen);
  if (!zustand.bearbeitbar) return { status: 409, body: { art: "nichtBearbeitbar", hinweise: zustand.hinweise } };
  const d = projektDateien(projekt);
  if (auftrag.hashes?.team !== d.hashes.team || (auftrag.hashes?.lokal ?? null) !== d.hashes.lokal) {
    return { status: 409, body: { art: "geaendert", grund: tx("speichern.geaendert") } };
  }
  const neu = aenderungAnwenden(d.team, d.lokal, auftrag);
  if (!neu.ok) return { status: 422, body: { art: "ungueltig", befunde: [befund(auftrag.aenderungen?.[0]?.pfad ?? "", neu.grund)] } };
  const alteFehler = new Set(pruefe(d.team, d.lokal).filter((b) => b.art === "fehler").map(schluesselVon));
  const neueFehler = pruefe(neu.team, neu.lokal).filter((b) => b.art === "fehler" && !alteFehler.has(schluesselVon(b)));
  if (neueFehler.length > 0) return { status: 422, body: { art: "ungueltig", befunde: neueFehler } };
  const aus = abgeschaltet(mergeWorkflowConfig(d.team, d.lokal).config, mergeWorkflowConfig(neu.team, neu.lokal).config);
  const bestaetigt = new Set(auftrag.bestaetigt ?? []);
  if (aus.some((a) => !bestaetigt.has(a.pfad))) return { status: 409, body: { art: "bestaetigung", abgeschaltet: aus } };
  schreibeProjekt(projekt, d, neu);
  return { status: 200, body: projektZustand(projekt, optionen) };
}

// ============================================================
// Abgeleitete Anzeigen (Plan #721 E1)
// ============================================================
//
// Anzeigen, die kein Feld der Datei sind: die Wirkung einer Paarungszeile, die
// Beispielbesetzung einer Prüfstufe, die Zahl der Kommandos je Bereich, die Spec-Datei eines
// Bereichs, der Treffer des Verweis-Musters und die Summe der Zeitbudgets. Sie stehen hier
// und nicht im Browser-Skript, weil `SEITEN_SKRIPT` ein Zeichenketten-Literal ist, das kein
// Test ausführt — dort läge die einzige Fassung dieser Regeln, die niemand prüft.

// SYNC: REVIEW_STUFEN und REVIEW_STUFEN_DEFAULT in kit/board/issue-review.mjs — Änderungen dort nachziehen.
const STUFEN = ["fachlich", "plan", "issue"];
const STUFEN_VORGABE = {
  fachlich: { reviewer: 2, rollen: ["form-beobachtbarkeit", "abgrenzung"] },
  plan: { reviewer: 2, rollen: ["architektur-bestand", "schnitt-abhaengigkeiten"] },
  issue: { reviewer: 1, rollen: ["pruefbarkeit"] },
};

/**
 * Die Vorgabe für `reviewStufen` als Ganzes, wenn der Block in der Datei fehlt — je Stufe die
 * Rollen des Katalogs, wie `REVIEW_STUFEN_DEFAULT` in `kit/board/issue-review.mjs` (Plan #1375 E5).
 * Sie steht als `vorgabe` am Eintrag des Pfads (Plan #721 E5), genau wie jeder andere Vorgabewert.
 */
const REVIEW_STUFEN_VORGABE = Object.fromEntries(STUFEN.map((s) => [s, STUFEN_VORGABE[s]]));

/**
 * Besetzung einer Prüfstufe. Fehlt der Block ganz, gilt die Bestandsvorgabe; fehlt nur diese
 * Stufe im vorhandenen Block, gilt sie hier ebenfalls — für die Anzeige ist eine Lücke
 * schlechter als ein Vorgabewert, und den Fehler nennt ohnehin die Prüfung.
 */
function besetzung(config, stufe) {
  const eintrag = istObjekt(config.reviewStufen?.[stufe]) ? config.reviewStufen[stufe] : STUFEN_VORGABE[stufe];
  return {
    anzahl: Number.isInteger(eintrag.reviewer) ? eintrag.reviewer : STUFEN_VORGABE[stufe].reviewer,
    rollen: Array.isArray(eintrag.rollen) ? eintrag.rollen : [],
  };
}

/** Wer den Fachplan, den Plan und das Arbeitspaket dieses Autors prüft, mit welcher Rolle. */
function wirkungFuer(config, autor) {
  const block = istObjekt(config.issueReview) ? config.issueReview : {};
  const reviewers = Array.isArray(block.reviewers) ? block.reviewers : [];
  const pairs = istObjekt(block.pairs) ? block.pairs : {};
  const stufen = {};
  for (const stufe of STUFEN) {
    const { anzahl, rollen } = besetzung(config, stufe);
    const gewaehlt = waehleReviewer(reviewers, autor, anzahl, pairs);
    stufen[stufe] = {
      pruefer: gewaehlt.gewaehlt.map((r, i) => ({ name: r.name, rolle: rollen[i] ?? null })),
      unterbesetzt: gewaehlt.unterbesetzt,
      quelle: gewaehlt.quelle,
    };
  }
  return stufen;
}

/** Je Autor mit eigener Paarung die Wirkung samt der Prüfer, die nirgends zum Zug kommen. */
function paarungsWirkung(config) {
  const pairs = istObjekt(config.issueReview?.pairs) ? config.issueReview.pairs : {};
  const out = {};
  for (const autor of Object.keys(pairs)) {
    const stufen = wirkungFuer(config, autor);
    const zumZug = new Set(Object.values(stufen).flatMap((s) => s.pruefer.map((p) => p.name)));
    const genannt = Array.isArray(pairs[autor]) ? pairs[autor] : [];
    out[autor] = { ...stufen, ungenutzt: genannt.filter((n, i) => genannt.indexOf(n) === i && !zumZug.has(n)) };
  }
  return out;
}

/**
 * Die Beispielbesetzung je Stufe (Kriterium 16): am ersten Autor mit eigener Paarung, ohne
 * Paarungen am ersten Reviewer. Ohne beides bleibt der Autor offen und die Regel greift.
 */
function beispielBesetzung(config) {
  const block = istObjekt(config.issueReview) ? config.issueReview : {};
  const pairs = istObjekt(block.pairs) ? block.pairs : {};
  const reviewers = Array.isArray(block.reviewers) ? block.reviewers : [];
  const autor = Object.keys(pairs)[0] ?? reviewers[0]?.name;
  return Object.fromEntries(Object.entries(wirkungFuer(config, autor)).map(([stufe, wirkung]) => [stufe, { autor: autor ?? null, ...wirkung }]));
}

/** Wie viele Prüfkommandos jeden Bereich nennen (Kriterium 20). */
function nutzungJeBereich(config) {
  const out = {};
  for (const name of Object.keys(istObjekt(config.checkAreas) ? config.checkAreas : {})) out[name] = 0;
  for (const check of Array.isArray(config.buildChecks) ? config.buildChecks : []) {
    for (const name of new Set(Array.isArray(check?.areas) ? check.areas : [])) {
      if (name in out) out[name] += 1;
    }
  }
  return out;
}

/**
 * Marke und Stufe der Gütemessung, oder `null`, wenn das Projekt keine benannt hat
 * (Issue #764). Die Oberfläche zeigt beides und bearbeitet es nicht: Der Block steht
 * in der Datei, und wer ihn dort ändert, soll am Bildschirm sehen, was gilt. Bei zwei
 * Blöcken zeigt die Anzeige den ersten — welcher gälte, ist offen, und genau das sagt
 * der Befund daneben.
 */
function gueteAnzeige(config) {
  const traeger = gueteTraeger(config)[0];
  if (!traeger) return null;
  return {
    cmd: typeof traeger.check.cmd === "string" ? traeger.check.cmd : "",
    marke: traeger.check.guete.marke,
    stufe: stufeVon(traeger.check),
  };
}

const KETTE_ZEIT = ["planMin", "paketeMin", "reviewMin", "abdeckungMin"];

/** Die Summe der Zeitbudgets, getrennt nach Kette und Umsetzungsstufe (Kriterium 26). */
function zeitbudget(config) {
  const kette = istObjekt(config.night?.kette) ? config.night.kette : {};
  const wert = (feld) => (typeof kette[feld] === "number" ? kette[feld] : vorgabeAus(`night.kette.${feld}`) ?? 0);
  return { kette: KETTE_ZEIT.reduce((summe, feld) => summe + wert(feld), 0), umsetzung: wert("umsetzungMin") };
}

/**
 * Die abgeleiteten Anzeigen — zu einem Teil die seinen, ohne Teil alle, je Teil-Kennung.
 * Ein Teil ohne abgeleitete Anzeige liefert ein leeres Objekt.
 */
export function abgeleitet(config, teil = null) {
  if (!istObjekt(config)) return {};
  const alle = {
    m2: () => ({ wirkung: paarungsWirkung(config) }),
    m3: () => ({ beispiel: beispielBesetzung(config) }),
    m4: () => ({ nutzung: nutzungJeBereich(config), guete: gueteAnzeige(config) }),
    m6: () => ({ zeit: zeitbudget(config) }),
  };
  if (teil === null || teil === undefined) return Object.fromEntries(Object.entries(alle).map(([kennung, baue]) => [kennung, baue()]));
  return alle[teil] ? alle[teil]() : {};
}

// ============================================================
// Änderungsliste und Vorschau (Plan #721 E1)
// ============================================================

const KURZ = 60;

/** Ein Wert als kurzer Text für den Fuß eines Teils. */
function kurz(wert) {
  const text = JSON.stringify(wert) ?? tx("aenderung.nichts");
  return text.length > KURZ ? `${text.slice(0, KURZ)}…` : text;
}

/**
 * Trägt die Unterschiede zweier Werte in `out`. Objekte und gleich lange Listen werden
 * durchlaufen, damit der Satz die geänderte Zeile nennt; bei verschieden langen Listen wäre
 * jeder Index hinter der Stelle verschoben — dort steht ein Satz über die Liste als Ganzes.
 */
function unterschied(pfad, alt, neu, out, namen) {
  if (gleich(alt, neu)) return;
  if (istObjekt(alt) && istObjekt(neu)) {
    for (const feld of new Set([...Object.keys(alt), ...Object.keys(neu)])) unterschied(`${pfad}.${feld}`, alt[feld], neu[feld], out, namen);
    return;
  }
  const name = anzeigePfad(pfad, namen);
  if (Array.isArray(alt) && Array.isArray(neu)) {
    if (alt.length === neu.length) {
      alt.forEach((wert, i) => unterschied(`${pfad}[${i}]`, wert, neu[i], out, namen));
      return;
    }
    out.push({ pfad, art: "geaendert", satz: tx("aenderung.eintraege", { name, neu: neu.length, alt: alt.length }) });
    return;
  }
  if (alt === undefined) out.push({ pfad, art: "neu", satz: tx("aenderung.neu", { name, wert: kurz(neu) }) });
  else if (neu === undefined) out.push({ pfad, art: "weg", satz: tx("aenderung.weg", { name }) });
  else out.push({ pfad, art: "geaendert", satz: tx("aenderung.geaendert", { name, neu: kurz(neu), alt: kurz(alt) }) });
}

/**
 * Je offener Änderung ein Satz für den Fuß des Teils (Kriterium 2). `teil` ist eine
 * Teil-Kennung und grenzt auf die Pfade ein, die dieser Teil bearbeitet, samt seinen
 * Folgepfaden; ohne Teil werden die Wurzelfelder beider Konfigurationen verglichen. Mit
 * `namen` nennt der Satz den Pfad in der Projektsprache (Issue #1441); `pfad` bleibt deutsch.
 */
export function aenderungsliste(alt, neu, teil = null, namen = null) {
  const eintrag = TEILE.find((t) => t.kennung === teil);
  const pfade = teil === null || teil === undefined
    ? [...new Set([...Object.keys(alt ?? {}), ...Object.keys(neu ?? {})])]
    : [...(eintrag?.pfade ?? []), ...(eintrag?.folgen ?? [])];
  const out = [];
  for (const pfad of pfade) unterschied(pfad, lies(alt ?? {}, pfad), lies(neu ?? {}, pfad), out, namen);
  return out;
}

/**
 * Prüft einen Auftrag, ohne ihn zu speichern: derselbe Weg wie `speichere` bis unmittelbar
 * vor das Schreiben. Liefert `{ befunde, aenderungen, abgeleitet, bestaetigung }` — die
 * Befunde am Pfad der betroffenen Zeile, die offenen Änderungen des Teils, die abgeleiteten
 * Anzeigen zum geänderten Stand und die noch fälligen Bestätigungen.
 *
 * Anders als `speichere` weist ein Befund nichts ab: Die Oberfläche soll ihn an der Zeile
 * zeigen, während getippt wird. Ein Fehler, der schon vorher in der Datei stand, taucht
 * nicht auf — nur ein neu entstehender; Warnungen stehen immer da (Kriterien 4 und 20).
 */
export function vorschau(projekt, auftrag, optionen) {
  return inSprache(spracheVon(projekt), () => vorschauIn(projekt, auftrag, optionen));
}

function vorschauIn(projekt, auftrag, optionen) {
  const zustand = projektZustand(projekt, optionen);
  if (!zustand.bearbeitbar) return { status: 409, body: { art: "nichtBearbeitbar", hinweise: zustand.hinweise } };
  const d = projektDateien(projekt);
  if (auftrag.hashes?.team !== d.hashes.team || (auftrag.hashes?.lokal ?? null) !== d.hashes.lokal) {
    return { status: 409, body: { art: "geaendert", grund: tx("speichern.geaendert") } };
  }
  const leer = { befunde: [], aenderungen: [], abgeleitet: {}, bestaetigung: [] };
  const neu = aenderungAnwenden(d.team, d.lokal, auftrag);
  if (!neu.ok) return { status: 200, body: { ...leer, befunde: [befund(auftrag.aenderungen?.[0]?.pfad ?? "", neu.grund)] } };
  const alteFehler = new Set(pruefe(d.team, d.lokal).filter((b) => b.art === "fehler").map(schluesselVon));
  const alt = mergeWorkflowConfig(d.team, d.lokal).config;
  const jetzt = mergeWorkflowConfig(neu.team, neu.lokal).config;
  const bestaetigt = new Set(auftrag.bestaetigt ?? []);
  return {
    status: 200,
    body: {
      befunde: pruefe(neu.team, neu.lokal).filter((b) => b.art !== "fehler" || !alteFehler.has(schluesselVon(b))),
      aenderungen: aenderungsliste(alt, jetzt, auftrag.teil ?? null, zustand.grundlagen?.namen ?? null),
      abgeleitet: abgeleitet(jetzt, auftrag.teil ?? null),
      bestaetigung: abgeschaltet(alt, jetzt).filter((a) => !bestaetigt.has(a.pfad)),
    },
  };
}

// ============================================================
// HTTP-Server (Plan #674 E16)
// ============================================================

const TOKEN_HEADER = "x-einstellungen-token";
const MAX_KOERPER = 1024 * 1024;

/** Host und Origin müssen auf diesen Server zeigen — gegen DNS-Rebinding und fremde Seiten. */
function herkunftErlaubt(req, port) {
  const erlaubt = [`127.0.0.1:${port}`, `localhost:${port}`];
  if (!erlaubt.includes(req.headers.host)) return false;
  const origin = req.headers.origin;
  return origin === undefined || erlaubt.some((h) => origin === `http://${h}`);
}

function tokenStimmt(req, token) {
  const gesendet = Buffer.from(String(req.headers[TOKEN_HEADER] ?? ""));
  const erwartet = Buffer.from(token);
  return gesendet.length === erwartet.length && timingSafeEqual(gesendet, erwartet);
}

function antworte(res, status, body, kopf = {}) {
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff", ...kopf });
  res.end(typeof body === "string" ? body : JSON.stringify(body));
}

function leseKoerper(req) {
  return new Promise((fertig, fehler) => {
    const teile = [];
    let laenge = 0;
    req.on("data", (teil) => {
      laenge += teil.length;
      if (laenge > MAX_KOERPER) {
        fehler(new Error(tx("api.zuGross")));
        req.destroy();
      } else {
        teile.push(teil);
      }
    });
    req.on("end", () => fertig(Buffer.concat(teile).toString("utf-8")));
    req.on("error", fehler);
  });
}

/**
 * Das Projekt eines API-Pfads samt der Frage, ob die Vorschau gemeint ist — `null`, wenn der
 * Pfad auf kein Projekt zeigt. Mehr als den einen zusätzlichen Abschnitt gibt es nicht.
 */
function projektAusPfad(pfad, projekte) {
  const treffer = pfad.match(/^\/api\/projekt\/([^/]+)(\/vorschau)?$/);
  if (!treffer) return null;
  try {
    const projekt = projekte.find((p) => p.name === decodeURIComponent(treffer[1]));
    return projekt ? { projekt, istVorschau: treffer[2] !== undefined } : null;
  } catch {
    return null;
  }
}

/**
 * Die Antworten ohne Projekt stehen in der Startsprache (`startSprache`), die eines Projekts in
 * dessen Sprache — das übernehmen `projektZustand`, `vorschau` und `speichere` selbst.
 * `/api/projekte` nennt die Startsprache, damit die Seite sie zeigt, bevor ein Projekt offen ist.
 */
async function beantworteApi(req, res, kontext) {
  const pfad = new URL(req.url, "http://127.0.0.1").pathname;
  const projekte = findeProjekte(kontext.ordner);
  const sprache = startSprache(kontext.ordner);
  if (req.method === "GET" && pfad === "/api/projekte") {
    const liste = inSprache(sprache, () => projekte.map((p) => {
      const stand = kitStandVon(p.pfad, kontext.home);
      return { name: p.name, kitStand: stand, ...standUrteil(stand, kontext.eigenerStand) };
    }));
    return antworte(res, 200, { projekte: liste, eigenerStand: kontext.eigenerStand, sprache });
  }
  const treffer = projektAusPfad(pfad, projekte);
  if (!treffer) return antworte(res, 404, { grund: inSprache(sprache, () => tx("api.projektUnbekannt")) });
  const { projekt, istVorschau } = treffer;
  if (req.method === "GET" && !istVorschau) return antworte(res, 200, projektZustand(projekt, kontext));
  if (req.method !== "POST") return antworte(res, 405, { grund: inSprache(sprache, () => tx("api.methode")) });
  let auftrag;
  try {
    auftrag = JSON.parse(await leseKoerper(req));
  } catch {
    return antworte(res, 400, { grund: inSprache(sprache, () => tx("api.rumpf")) });
  }
  const ergebnis = istVorschau ? vorschau(projekt, auftrag, kontext) : speichere(projekt, auftrag, kontext);
  return antworte(res, ergebnis.status, ergebnis.body);
}

function beantworte(req, res, kontext, token, port) {
  const sprache = startSprache(kontext.ordner);
  const grund = (schluessel) => ({ grund: inSprache(sprache, () => tx(schluessel)) });
  if (!herkunftErlaubt(req, port)) return antworte(res, 403, grund("api.herkunft"));
  const pfad = new URL(req.url, "http://127.0.0.1").pathname;
  if (!pfad.startsWith("/api/")) {
    if (req.method === "GET" && pfad === "/") {
      const { html, csp } = inSprache(sprache, () => seite(sprache));
      return antworte(res, 200, html, { "Content-Type": "text/html; charset=utf-8", "Content-Security-Policy": csp, "Referrer-Policy": "no-referrer" });
    }
    return antworte(res, 404, grund("api.nichtGefunden"));
  }
  if (!tokenStimmt(req, token)) return antworte(res, 403, grund("api.token"));
  return beantworteApi(req, res, kontext).catch((e) => antworte(res, 500, { grund: e.message }));
}

/**
 * Startet den Server auf 127.0.0.1. Liefert `{ server, port, token, url }`. `eigenerStand`
 * und `home` sind für Tests überschreibbar; ohne sie gelten KIT_VERSION und das Home des Nutzers.
 */
export function starteServer({ ordner, port = 0, home = homedir(), eigenerStand = KIT_VERSION, token = randomBytes(24).toString("hex") }) {
  const kontext = { ordner: resolve(ordner), home, eigenerStand };
  const server = createServer((req, res) => beantworte(req, res, kontext, token, server.address().port));
  return new Promise((fertig, fehler) => {
    server.once("error", fehler);
    server.listen(port, "127.0.0.1", () => {
      const p = server.address().port;
      fertig({ server, port: p, token, url: `http://127.0.0.1:${p}/#token=${token}` });
    });
  });
}

