  if (teil.titel) kopf.append(el("span", "feldpfad mono", teil.eintraege.map(function (e) { return zeigePfad(e.pfad); }).join(" · ")));
  kopf.append(el("span", "etikett", erster.persoenlichErlaubt ? tx("platte.teamOderPersoenlich") : tx("platte.team")));
  p.append(kopf);
